function practiceHTML(unit){const pool=bankPool(unit);if(!pool.length)return'';const q=ensureQuestion(unit);const levels=[...new Set(pool.map(x=>x.level))];const level=state.practiceLevels[unit];const buttons=levels.map(k=>`<button class="${k===level?'active':''}" data-level="${k}" data-unit="${unit}">${levelName(k)}</button>`).join('');const fields=q.fields.map((f,i)=>`<div class="answer-row"><label>${L(f.labelEn,f.labelId)}</label>${fieldHTML(f,i,q.id)}</div>`).join('');const solved=state.solved[unit+':'+level]||0;const history=state.questionHistory[unit]||[q.id];const pos=state.historyPos[unit]??history.length-1;const prevId=pos>0?history[pos-1]:null;const prevQ=prevId?QUESTION_BANK[prevId]:null;const familyChoices=[...new Set(pool.map(x=>x.family))].sort().map(f=>`<option value="${f}">${familyLabel(f)}</option>`).join('');const questionChoices=pool.map(x=>`<option value="${x.id}" ${x.id===q.id?'selected':''}>${x.id} · ${levelName(x.level)} · ${L(x.titleEn,x.titleId)}</option>`).join('');const work=state.workpad[q.id]||'';return `<div class="practice-lab" data-practice-unit="${unit}" data-qid="${q.id}"><div class="scene-label" style="color:#8fd0c7">${t('practice')}</div><h3>${L('Practice from the canonical question bank','Latihan dari bank soal kanonik')}</h3><div class="lab-intro">${t('practiceIntro')}</div><div class="practice-summary"><span>${L('Solved at this level','Terselesaikan pada tingkat ini')}: <strong>${solved}</strong></span><span>${L('Current family','Keluarga soal saat ini')}: <strong>${familyLabel(q.family)}</strong></span>${prevQ?`<span>${L('Previous','Sebelumnya')}: <strong>${prevQ.id} · ${levelName(prevQ.level)}</strong></span>`:''}</div><div class="level-selector">${buttons}</div>${state.teacher?`<div class="teacher-bank-controls"><label>${L('Problem family','Keluarga soal')}<select data-family-select><option value="">${L('All families','Semua keluarga')}</option>${familyChoices}</select></label><label>${L('Exact question','Soal tertentu')}<select data-question-select>${questionChoices}</select></label></div>`:''}<div class="practice-card"><div class="practice-meta"><span class="meta-pill">${levelName(q.level)}</span><span class="meta-pill">${q.id}</span><span class="meta-pill">${familyLabel(q.family)}</span><span class="meta-pill">${levelDesc(q.level)}</span></div><h4>${L(q.titleEn,q.titleId)}</h4><div class="strategy-strip"><strong>${L('Reasoning target','Target penalaran')}:</strong> ${L(q.strategyEn,q.strategyId)}</div><div class="problem-text">${L(q.textEn,q.textId)}</div><div class="answer-grid">${fields}</div><details class="workpad"><summary>${L('Working space','Ruang kerja')}</summary><textarea data-workpad placeholder="${L('Write intermediate steps here…','Tulis langkah antara di sini…')}">${escAttr(work)}</textarea></details><div class="practice-actions"><button class="check-btn" data-check-practice>${t('check')}</button><button class="hint-btn" data-hint-practice>${t('hint')}</button><button class="reset-btn" data-reset-practice>${t('reset')}</button><button class="change-btn" data-change-problem ${bankPool(unit,q.level).length<=1?`disabled title="${L('No alternate canonical problem at this level here','Belum ada soal kanonik lain pada tingkat ini')}"`:''}>${bankPool(unit,q.level).length<=1?L('No alternate in this level','Belum ada variasi lain di tingkat ini'):L('Change Problem','Ganti Soal')}</button><button class="previous-problem-btn" data-previous-problem ${pos<=0?'disabled':''}>${L('Previous Problem','Soal Sebelumnya')}</button></div><div class="hint-box" data-hint-box></div><button class="final-support-btn" data-final-support disabled>${L('Final Support','Bantuan Terakhir')}</button><div class="solution-support" data-solution-support></div><div class="feedback" data-feedback></div></div></div>`}
function triangleSvg({A=[55,235],B=[275,235],C=[135,65],labels=true,right=false,showAltitude=false,sideLabels={},angleLabels={}}={}){const [ax,ay]=A,[bx,by]=B,[cx,cy]=C;let alt='';if(showAltitude){const dx=bx-ax,dy=by-ay;const tt=((cx-ax)*dx+(cy-ay)*dy)/(dx*dx+dy*dy);const fx=ax+tt*dx,fy=ay+tt*dy;alt=`<line x1="${cx}" y1="${cy}" x2="${fx}" y2="${fy}" stroke="#2d7f83" stroke-width="2" stroke-dasharray="6 5"/><text x="${fx+8}" y="${fy-8}" fill="#2d7f83">D</text>`}const rmark=right?`<path d="M ${ax+18} ${ay} L ${ax+18} ${ay-18} L ${ax} ${ay-18}" fill="none" stroke="#9a6b1f" stroke-width="2"/>`:'';return `<svg viewBox="0 0 330 280" role="img" aria-label="${L('triangle diagram using given information only','diagram segitiga yang hanya menampilkan informasi diketahui')}"><polygon points="${ax},${ay} ${bx},${by} ${cx},${cy}" fill="#f7fbfa" stroke="#274d68" stroke-width="2.5"/>${alt}${rmark}${labels?`<text x="${ax-18}" y="${ay+18}">A</text><text x="${bx+8}" y="${by+18}">B</text><text x="${cx-4}" y="${cy-12}">C</text>`:''}${sideLabels.AB?`<text x="${(ax+bx)/2-10}" y="${(ay+by)/2+24}" fill="#356f9a">${sideLabels.AB}</text>`:''}${sideLabels.AC?`<text x="${(ax+cx)/2-35}" y="${(ay+cy)/2}" fill="#356f9a">${sideLabels.AC}</text>`:''}${sideLabels.BC?`<text x="${(bx+cx)/2+12}" y="${(by+cy)/2}" fill="#356f9a">${sideLabels.BC}</text>`:''}${angleLabels.A?`<text x="${ax+18}" y="${ay-12}" fill="#8a681d">${angleLabels.A}</text>`:''}${angleLabels.B?`<text x="${bx-40}" y="${by-12}" fill="#8a681d">${angleLabels.B}</text>`:''}${angleLabels.C?`<text x="${cx+8}" y="${cy+24}" fill="#8a681d">${angleLabels.C}</text>`:''}</svg>`}

