function cosineExplorerSvg(angle){const C=[145,235],A=[325,235],scale=18,r=angle*Math.PI/180,B=[C[0]+7*scale*Math.cos(r),C[1]-7*scale*Math.sin(r)],rr=29,ax=C[0]+rr*Math.cos(r),ay=C[1]-rr*Math.sin(r),m1=[(C[0]+B[0])/2,(C[1]+B[1])/2],m2=[(A[0]+B[0])/2,(A[1]+B[1])/2];return '<svg class="geometry-svg cosine-svg" viewBox="0 0 370 300" role="img" aria-label="'+L('Sides a and b enclose variable included angle C','Sisi a dan b mengapit sudut C yang berubah')+'"><polygon data-cos-fill="" points="'+C[0]+','+C[1]+' '+A[0]+','+A[1]+' '+B[0]+','+B[1]+'" fill="#f7fbfa"/><line class="triangle-edge" data-cos-ca="" x1="'+C[0]+'" y1="'+C[1]+'" x2="'+A[0]+'" y2="'+A[1]+'"/><line class="triangle-edge" data-cos-cb="" x1="'+C[0]+'" y1="'+C[1]+'" x2="'+B[0]+'" y2="'+B[1]+'"/><line class="triangle-edge" data-cos-ab="" x1="'+A[0]+'" y1="'+A[1]+'" x2="'+B[0]+'" y2="'+B[1]+'"/><circle class="vertex-dot" cx="'+C[0]+'" cy="'+C[1]+'" r="3.5"/><circle class="vertex-dot" cx="'+A[0]+'" cy="'+A[1]+'" r="3.5"/><circle class="vertex-dot" data-cos-bdot="" cx="'+B[0]+'" cy="'+B[1]+'" r="3.5"/><text class="vertex-label" x="334" y="254">A</text><text class="vertex-label" x="130" y="254">C</text><text class="vertex-label" data-cos-blabel="" x="'+(B[0]+8)+'" y="'+(B[1]-10)+'">B</text><path data-cos-arc="" class="angle-arc" d="M '+(C[0]+rr)+' '+C[1]+' A '+rr+' '+rr+' 0 0 0 '+ax+' '+ay+'"/><text class="angle-label" data-cos-angle-label="" x="'+(C[0]+(angle>130?68:42)*Math.cos(r/2))+'" y="'+(C[1]-(angle>130?68:42)*Math.sin(r/2)-4)+'" text-anchor="middle">'+angle+'°</text><text class="side-label" x="231" y="264" text-anchor="middle">b = 10</text><text class="side-label" data-cos-7="" x="'+(m1[0]-14*Math.sin(r))+'" y="'+(m1[1]-14*Math.cos(r))+'" text-anchor="middle">a = 7</text><text class="side-label" data-cos-x="" x="'+(m2[0]+14*(A[1]-B[1])/Math.hypot(B[0]-A[0],B[1]-A[1]))+'" y="'+(m2[1]-14*(A[0]-B[0])/Math.hypot(B[0]-A[0],B[1]-A[1]))+'" text-anchor="middle">c = '+fmt(Math.sqrt(7*7+10*10-2*7*10*Math.cos(r)),2)+'</text></svg>'}
function cosineCaseNote(angle,c){const state=angle<90?'acute':angle===90?'right':'obtuse';return state==='right'?L(`C=90°: c≈${fmt(c,2)} and c²=7²+10² (Pythagoras).`,'C=90°: c≈'+fmt(c,2)+' dan c²=7²+10² (Pythagoras).'):state==='acute'?L(`C=${angle}° is acute; cos C>0, so the cosine term reduces c. Here c≈${fmt(c,2)}.`,'C='+angle+'° lancip; cos C>0, sehingga suku cosinus mengurangi c. Di sini c≈'+fmt(c,2)+'.'):L(`C=${angle}° is obtuse; cos C<0, so subtracting 2ab cos C increases c. Here c≈${fmt(c,2)}.`,'C='+angle+'° tumpul; cos C<0, sehingga pengurangan 2ab cos C memperbesar c. Di sini c≈'+fmt(c,2)+'.')}
function updateCosExplorer(root,angle){const C=[145,235],A=[325,235],scale=18,r=angle*Math.PI/180,B=[C[0]+7*scale*Math.cos(r),C[1]-7*scale*Math.sin(r)],pt=v=>v.map(x=>Number(x).toFixed(2)).join(',');root.querySelector('[data-cos-fill]').setAttribute('points',pt(C)+' '+pt(A)+' '+pt(B));for(const [sel,u,v] of [['[data-cos-ca]',C,A],['[data-cos-cb]',C,B],['[data-cos-ab]',A,B]]){const e=root.querySelector(sel);e.setAttribute('x1',u[0]);e.setAttribute('y1',u[1]);e.setAttribute('x2',v[0]);e.setAttribute('y2',v[1])}const dot=root.querySelector('[data-cos-bdot]');dot.setAttribute('cx',B[0]);dot.setAttribute('cy',B[1]);const bl=root.querySelector('[data-cos-blabel]');bl.setAttribute('x',B[0]+8);bl.setAttribute('y',B[1]-10);const rr=29,x=C[0]+rr*Math.cos(r),y=C[1]-rr*Math.sin(r);root.querySelector('[data-cos-arc]').setAttribute('d','M '+(C[0]+rr)+' '+C[1]+' A '+rr+' '+rr+' 0 0 0 '+x+' '+y);const label=root.querySelector('[data-cos-angle-label]');label.textContent=angle+'°';const angleLabelRadius=angle>130?68:42;label.setAttribute('x',C[0]+angleLabelRadius*Math.cos(r/2));label.setAttribute('y',C[1]-angleLabelRadius*Math.sin(r/2)-4);const cValue=Math.sqrt(7*7+10*10-2*7*10*Math.cos(r));const cLabel=root.querySelector('[data-cos-x]');cLabel.textContent='c = '+fmt(cValue,2);const m1=[(C[0]+B[0])/2,(C[1]+B[1])/2],m2=[(A[0]+B[0])/2,(A[1]+B[1])/2],sl=root.querySelector('[data-cos-7]'),sx=root.querySelector('[data-cos-x]');sl.setAttribute('x',m1[0]-14*Math.sin(r));sl.setAttribute('y',m1[1]-14*Math.cos(r));sx.setAttribute('x',m2[0]+14*(A[1]-B[1])/Math.hypot(B[0]-A[0],B[1]-A[1]));sx.setAttribute('y',m2[1]-14*(A[0]-B[0])/Math.hypot(B[0]-A[0],B[1]-A[1]))}
function ambiguousSvg(revealed){return '<svg class="geometry-svg ambiguous-svg '+(revealed?'revealed':'')+'" viewBox="0 0 360 360" role="img" aria-label="'+L('A fixed-radius circle meets the ray twice after reveal','Lingkaran berjari-jari tetap memotong sinar dua kali setelah ditampilkan')+'"><line class="baseline" x1="25" y1="215" x2="330" y2="215"/><text class="vertex-label" x="30" y="235">A</text><text class="vertex-label" x="232" y="235">C</text><path class="given-ray" d="M42 215 L112 166"/><path class="extension-ray" d="M112 166 L266 58"/><circle class="fixed-circle" cx="227" cy="215" r="125"/><polygon class="first-triangle" points="42,215 227,215 112,166"/><line class="first-radius" x1="227" y1="215" x2="112" y2="166"/><circle class="intersection" cx="112" cy="166" r="5"/><text class="vertex-label" x="100" y="155">B₁</text><path class="angle-arc" d="M67 215 A25 25 0 0 0 62.5 200.7"/><text class="angle-label" x="80" y="195">35°</text><g class="second-candidate"><polygon class="second-triangle" points="42,215 227,215 220.3,90.2"/><line class="second-radius" x1="227" y1="215" x2="220.3" y2="90.2"/><circle class="intersection" cx="220.3" cy="90.2" r="5"/><text class="vertex-label" x="235" y="88">B₂</text></g><text class="side-label" x="134" y="237" text-anchor="middle">b fixed</text><text class="side-label" x="183" y="177">a fixed</text><text class="side-label second-side-label" x="237" y="151">same a</text></svg>'}
function updateCompass(svg,beta){const cx=150,cy=150,r=100,rad=beta*Math.PI/180,x=cx+r*Math.sin(rad),y=cy-r*Math.cos(rad),ar=44,ax=cx+ar*Math.sin(rad),ay=cy-ar*Math.cos(rad);svg.querySelector('[data-bearing-ray]').setAttribute('x2',x);svg.querySelector('[data-bearing-ray]').setAttribute('y2',y);svg.querySelector('[data-bearing-endpoint]').setAttribute('cx',x);svg.querySelector('[data-bearing-endpoint]').setAttribute('cy',y);svg.querySelector('[data-bearing-arc]').setAttribute('d','M '+cx+' '+(cy-ar)+' A '+ar+' '+ar+' 0 '+(beta>180?1:0)+' 1 '+ax+' '+ay);const lab=svg.querySelector('[data-bearing-beta]'),mid=rad/2;lab.setAttribute('x',cx+58*Math.sin(mid));lab.setAttribute('y',cy-58*Math.cos(mid)+4);lab.textContent='β='+String(beta).padStart(3,'0')+'°';svg.setAttribute('aria-label',L('Bearing '+String(beta).padStart(3,'0')+' degrees clockwise from North','Bearing '+String(beta).padStart(3,'0')+' derajat searah jarum jam dari Utara'))}

function compassSvg(beta=40,d=100){const r=100,cx=150,cy=150,rad=beta*Math.PI/180,x=cx+r*Math.sin(rad),y=cy-r*Math.cos(rad),ar=44,ax=cx+ar*Math.sin(rad),ay=cy-ar*Math.cos(rad),mid=rad/2;return '<svg class="geometry-svg compass-svg" viewBox="0 0 300 300" role="img" aria-label="'+L('Bearing ray measured clockwise from North','Sinar bearing diukur searah jarum jam dari Utara')+'"><circle cx="150" cy="150" r="105" fill="#f8fbfa" stroke="#d5e0df"/><line x1="150" y1="42" x2="150" y2="258" stroke="#9fb1b5"/><line x1="42" y1="150" x2="258" y2="150" stroke="#d6dfdf"/><text x="150" y="29" text-anchor="middle" font-weight="800">N</text><text x="270" y="155">E</text><text x="150" y="280" text-anchor="middle">S</text><text x="22" y="155">W</text><line data-bearing-ray="" x1="150" y1="150" x2="'+x+'" y2="'+y+'" stroke="#2d7f83" stroke-width="4"/><circle data-bearing-endpoint="" cx="'+x+'" cy="'+y+'" r="5" fill="#2d7f83"/><path data-bearing-arc="" d="M 150 106 A 44 44 0 '+(beta>180?1:0)+' 1 '+ax+' '+ay+'" fill="none" stroke="#c9962e" stroke-width="3"/><text data-bearing-beta="" x="'+(cx+58*Math.sin(mid))+'" y="'+(cy-58*Math.cos(mid)+4)+'" text-anchor="middle" class="bearing-angle-label">β='+String(beta).padStart(3,'0')+'°</text></svg>'}
function chordSvg(route='cos'){const O=[170,145],A=[78,81],B=[78,209],M=[78,145];const bisect=route==='bisect';return `<svg class="geometry-svg chord-svg ${bisect?'route-bisect':'route-cos'}" viewBox="0 0 340 285" role="img" aria-label="${L(bisect?'Chord split by a perpendicular radius into two right triangles':'Whole isosceles triangle formed by two radii and a chord',bisect?'Tali busur dibagi oleh jari-jari tegak lurus menjadi dua segitiga siku-siku':'Segitiga sama kaki utuh yang dibentuk dua jari-jari dan satu tali busur')}"><circle cx="170" cy="145" r="112" fill="#f8fbfa" stroke="#d5e0df" stroke-width="1.5"/><line class="chord-radius" x1="170" y1="145" x2="78" y2="81"/><line class="chord-radius" x1="170" y1="145" x2="78" y2="209"/><line class="chord-edge" x1="78" y1="81" x2="78" y2="209"/><path class="theta-arc" d="M 145 128 A 29 29 0 0 0 145 162"/><text class="angle-label" x="130" y="150" text-anchor="middle">${bisect?'':'θ'}</text><text class="side-label" x="119" y="100">r</text><text class="side-label" x="119" y="200">r</text><text class="side-label" x="62" y="150" text-anchor="middle">${bisect?'':'c = AB'}</text><text class="vertex-label" x="174" y="141">O</text><text class="vertex-label" x="62" y="73">A</text><text class="vertex-label" x="62" y="224">B</text>${bisect?`<line class="bisector-line" x1="170" y1="145" x2="78" y2="145"/><path class="right-mark" d="M 89 145 L 89 156 L 78 156"/><path class="half-angle-arc" d="M 145 128 A 29 29 0 0 0 145 145"/><text class="angle-label" x="141" y="139" text-anchor="middle">θ/2</text><text class="side-label" x="58" y="116" text-anchor="middle">c/2</text><text class="side-label" x="58" y="181" text-anchor="middle">c/2</text><circle cx="78" cy="145" r="3.5" fill="#2d7f83"/><text class="vertex-label" x="83" y="163">M</text>`:''}</svg>`}
function elevationSvg(){return `<svg class="geometry-svg elevation-svg" viewBox="0 0 440 300" role="img" aria-label="${L('Vertical cliff with parallel horizontals, observer line of sight, and equal 28 degree depression and elevation angles','Tebing vertikal dengan garis horizontal sejajar, garis pandang pengamat, dan sudut depresi serta elevasi 28 derajat yang sama')}"><line x1="45" y1="245" x2="430" y2="245" class="ground-line"/><line x1="80" y1="75" x2="80" y2="245" class="cliff-line"/><line x1="80" y1="75" x2="399.5" y2="245" class="sight-line"/><line x1="80" y1="75" x2="430" y2="75" class="observer-horizontal"/><line x1="80" y1="245" x2="410" y2="245" class="ground-horizontal"/><path class="right-mark" d="M 80 227 L 98 227 L 98 245"/><path class="angle-arc depression-arc" d="M 115 75 A 35 35 0 0 1 110.9 91.4"/><text class="angle-label" x="122" y="91">28°</text><path class="angle-arc elevation-arc" d="M 364.5 245 A 35 35 0 0 1 368.6 228.6"/><text class="angle-label" x="341" y="226">28°</text><text class="vertex-label" x="66" y="67">O</text><text class="diagram-caption" x="138" y="64">${L('observer horizontal','horizontal pengamat')}</text><text class="diagram-caption" x="136" y="111">${L('line of sight','garis pandang')}</text><text class="side-label" x="55" y="166" text-anchor="end">50 m</text><text class="vertex-label" x="402" y="258">B</text><text class="diagram-caption" x="350" y="278">${L('boat','kapal')}</text><circle cx="80" cy="75" r="4" fill="#17324a"/><circle cx="399.5" cy="245" r="4" fill="#17324a"/></svg>`}
function gatewaySvg(step=1){return `<svg class="geometry-svg gateway-svg stage-${step}" viewBox="0 0 380 330" role="img" aria-label="${L('Quadrilateral split into first solvable triangle ABC and target triangle ACD, sharing gateway diagonal AC','Segiempat dibagi menjadi segitiga pertama ABC dan segitiga target ACD yang berbagi diagonal penghubung AC')}"><polygon class="gateway-first" points="90,174 150,70 232.5,212.9"/><polygon class="gateway-target" points="90,174 232.5,212.9 186.1,289"/><path class="gateway-edge" d="M90 174 L150 70 L232.5 212.9 L186.1 289 L90 174"/><line class="gateway-diagonal" x1="90" y1="174" x2="232.5" y2="212.9"/><path class="gateway-angle first-angle" d="M 162 91 A 24 24 0 0 1 138 91"/><text class="angle-label" x="150" y="107" text-anchor="middle">60°</text><path class="gateway-angle target-angle" d="M 118.9 181.9 A 30 30 0 0 1 109.2 197"/><text class="angle-label target-angle-label" x="128" y="201">35°</text><text class="vertex-label" x="73" y="190">A</text><text class="vertex-label" x="145" y="54">B</text><text class="vertex-label" x="239" y="217">C</text><text class="vertex-label" x="188" y="307">D</text><text class="side-label given-ab" x="103" y="119" transform="rotate(-60 103 119)">8</text><text class="side-label given-bc" x="186" y="135" transform="rotate(60 186 135)">11</text><text class="side-label given-ad" x="129" y="239" transform="rotate(50 129 239)">10</text><text class="side-label target-unknown" x="218" y="260" transform="rotate(-59 218 260)">?</text><text class="gateway-label" x="163" y="177" text-anchor="middle">${step>=2?'g = AC':'AC'}</text></svg>`}
function gatewayStepText(step){return step===1?L('Step 1: △ABC has the given SAS data. Solve this first; the target triangle stays muted.','Langkah 1: △ABC memiliki data SAS yang diketahui. Selesaikan ini dahulu; segitiga target dibuat redup.'):step===2?L('Step 2: AC is the gateway quantity produced by △ABC. The label g marks it without revealing its value.','Langkah 2: AC adalah besaran penghubung yang diperoleh dari △ABC. Label g menandainya tanpa membocorkan nilainya.'):L('Step 3: transfer the same AC=g into target △ACD, alongside AD and included angle CAD. Now the target triangle has SAS data.','Langkah 3: pindahkan AC=g yang sama ke segitiga target △ACD, bersama AD dan sudut apit CAD. Kini segitiga target memiliki data SAS.')}
function reversePairSvg(){return `<svg class="geometry-svg reverse-svg" viewBox="0 0 430 270" role="img" aria-label="${L('Two triangles with equal 40 degree included angles and explicitly equal areas','Dua segitiga dengan sudut apit 40 derajat dan luas yang dinyatakan setara')}"><text class="diagram-caption equality-premise" x="215" y="30" text-anchor="middle">${L('Given: Area △ABC = Area △DEF','Diketahui: luas △ABC = luas △DEF')}</text><polygon class="reverse-triangle" points="38,220 150,220 166.7,112"/><polygon class="reverse-triangle second" points="220,220 304,220 391.5,76"/><path class="angle-arc" d="M 66 220 A 28 28 0 0 0 59.4 202"/><path class="angle-arc" d="M 248 220 A 28 28 0 0 0 241.4 202"/><text class="angle-label" x="76" y="200">40°</text><text class="angle-label" x="258" y="200">40°</text><text class="side-label" x="94" y="243" text-anchor="middle">8</text><text class="side-label" x="84" y="166" transform="rotate(-40 84 166)">12</text><text class="side-label" x="262" y="243" text-anchor="middle">6</text><text class="side-label" x="307" y="148" transform="rotate(-40 307 148)">x</text><text class="vertex-label" x="28" y="235">A</text><text class="vertex-label" x="151" y="238">B</text><text class="vertex-label" x="164" y="89">C</text><text class="vertex-label" x="211" y="235">D</text><text class="vertex-label" x="305" y="238">E</text><text class="vertex-label" x="397" y="77">F</text></svg>`}
function parameterTriangleSvg(){return `<svg class="geometry-svg parameter-svg" viewBox="0 0 330 280" role="img" aria-label="${L('Triangle with AB=x+1 and AC=x+3 enclosing angle A=60 degrees, opposite side BC=7','Segitiga dengan AB=x+1 dan AC=x+3 mengapit sudut A=60 derajat, sisi di hadapannya BC=7')}"><polygon points="60,235 164,235 130,114" fill="#f7fbfa" stroke="#274d68" stroke-width="2.7"/><path class="angle-arc" d="M 91 235 A 31 31 0 0 0 75.5 208.2"/><text class="angle-label" x="96" y="216">60°</text><text class="vertex-label" x="46" y="253">A</text><text class="vertex-label" x="168" y="253">B</text><text class="vertex-label" x="126" y="100">C</text><text class="side-label" x="110" y="261" text-anchor="middle">x+1</text><text class="side-label" x="77" y="166" text-anchor="middle" transform="rotate(-60 77 166)">x+3</text><text class="side-label" x="153" y="172" text-anchor="middle" transform="rotate(74 153 172)">7</text></svg>`}
function feasibleGeom(b){const A=40*Math.PI/180,scale=16,a=6,disc=a*a-b*b*Math.sin(A)**2;let roots=[];if(disc>=-1e-9){const d=Math.sqrt(Math.max(0,disc)),t0=b*Math.cos(A)-d,t1=b*Math.cos(A)+d;for(const t of [t0,t1])if(t>1e-7&&!roots.some(x=>Math.abs(x-t)<1e-6))roots.push(t)}const count=roots.length,critical=6/Math.sin(A),tangent=Math.abs(disc)<1e-7;return {A,scale,a,disc,roots,count,critical,tangent}}
function feasiblePoint(b,t,g){const ax=40,ay=245,cx=ax+b*g.scale;return [ax+t*g.scale*Math.cos(g.A),ay-t*g.scale*Math.sin(g.A),cx,ay]}
function feasibilitySvg(b){const g=feasibleGeom(b),ax=40,ay=245,cx=ax+b*g.scale,ang=g.A,rayX=320,rayY=ay-(rayX-ax)*Math.tan(ang),candidates=g.roots.map((t,i)=>{const [x,y]=feasiblePoint(b,t,g),dx=x-cx,dy=y-ay,len=Math.hypot(dx,dy),mx=(cx+x)/2-10*dy/len,my=(ay+y)/2+10*dx/len,label=g.count===2?'B'+(i+1):'B';return `<polygon class="feasible-triangle ${i?'second':'first'}" data-feasible-triangle="${i}" points="${ax},${ay} ${cx},${ay} ${x},${y}"/><line class="feasible-radius ${i?'second':''}" data-feasible-radius="${i}" x1="${cx}" y1="${ay}" x2="${x}" y2="${y}"/><circle class="feasible-hit ${i?'second':''}" data-feasible-hit="${i}" cx="${x}" cy="${y}" r="5"/><text class="vertex-label" data-feasible-b-label-point="${i}" x="${x+(t<4?14:7)}" y="${y+(t<4?24:-8)}">${label}</text><text class="side-label" data-feasible-a-label="${i}" x="${mx}" y="${my}" display="${g.count===2&&i===0?'none':''}">a=6</text>`}).join('')+[0,1].slice(g.roots.length).map(i=>`<polygon class="feasible-triangle ${i?'second':'first'}" data-feasible-triangle="${i}" points="" display="none"/><line class="feasible-radius ${i?'second':''}" data-feasible-radius="${i}" display="none"/><circle class="feasible-hit ${i?'second':''}" data-feasible-hit="${i}" r="5" display="none"/><text class="vertex-label" data-feasible-b-label-point="${i}" display="none"/><text class="side-label" data-feasible-a-label="${i}" display="none"/>`).join(''),right=(g.tangent&&g.roots.length)?(()=>{const t=g.roots[0],[x,y]=feasiblePoint(b,t,g),ux=Math.cos(g.A),uy=-Math.sin(g.A),vx=(cx-x)/(g.a*g.scale),vy=(ay-y)/(g.a*g.scale),n=11;return `M ${x-ux*n} ${y-uy*n} l ${vx*n} ${vy*n} l ${ux*n} ${uy*n} Z`})():'';return `<svg class="geometry-svg feasible-svg" viewBox="0 0 360 345" role="img" aria-label="${L('SSA construction with '+g.count+' possible triangle configuration(s)','Konstruksi SSA dengan '+g.count+' konfigurasi segitiga yang mungkin')}"><line class="feasible-base" x1="40" y1="245" x2="350" y2="245"/><line class="feasible-ray" x1="40" y1="245" x2="${rayX}" y2="${rayY}"/><path class="angle-arc" d="M 76 245 A 36 36 0 0 0 ${40+36*Math.cos(ang)} ${245-36*Math.sin(ang)}"/><text class="angle-label" x="76" y="220">40°</text><circle class="feasible-circle" data-feasible-circle="" cx="${cx}" cy="245" r="96"/><circle class="vertex-dot" cx="40" cy="245" r="4"/><circle class="vertex-dot" data-feasible-center="" cx="${cx}" cy="245" r="4"/>${candidates}<path class="feasible-right-mark" data-feasible-right="" d="${right}" ${right?'':'display="none"'}/><text class="vertex-label" x="26" y="264">A</text><text class="vertex-label" data-feasible-c="" x="${cx-3}" y="266">C</text><text class="side-label" data-feasible-b-label="" x="${(40+cx)/2}" y="264" text-anchor="middle">b</text></svg>`}
function updateFeasibility(root,b){const g=feasibleGeom(b),ax=40,ay=245,cx=ax+b*g.scale;root.setAttribute('aria-label',L('SSA construction with '+g.count+' possible triangle configuration(s)','Konstruksi SSA dengan '+g.count+' konfigurasi segitiga yang mungkin'));root.querySelector('[data-feasible-circle]').setAttribute('cx',cx);const center=root.querySelector('[data-feasible-center]');center.setAttribute('cx',cx);root.querySelector('[data-feasible-c]').setAttribute('x',cx-3);const bl=root.querySelector('[data-feasible-b-label]');bl.setAttribute('x',(ax+cx)/2);bl.textContent='b = '+Number(b).toFixed(2);for(let i=0;i<2;i++){const poly=root.querySelector(`[data-feasible-triangle="${i}"]`),line=root.querySelector(`[data-feasible-radius="${i}"]`),hit=root.querySelector(`[data-feasible-hit="${i}"]`),lab=root.querySelector(`[data-feasible-b-label-point="${i}"]`),al=root.querySelector(`[data-feasible-a-label="${i}"]`),t=g.roots[i];if(t==null){poly.setAttribute('display','none');line.setAttribute('display','none');hit.setAttribute('display','none');lab.setAttribute('display','none');al.setAttribute('display','none');continue}const [x,y]=feasiblePoint(b,t,g);poly.setAttribute('display','');poly.setAttribute('points',`${ax},${ay} ${cx},${ay} ${x},${y}`);line.setAttribute('display','');line.setAttribute('x1',cx);line.setAttribute('y1',ay);line.setAttribute('x2',x);line.setAttribute('y2',y);hit.setAttribute('display','');hit.setAttribute('cx',x);hit.setAttribute('cy',y);lab.setAttribute('display','');lab.setAttribute('x',x+(t<4?14:7));lab.setAttribute('y',y+(t<4?24:-8));lab.textContent=g.count===2?'B'+(i+1):'B';const mx=(cx+x)/2,my=(ay+y)/2,dx=x-cx,dy=y-ay,len=Math.hypot(dx,dy);al.setAttribute('display',g.count===2&&i===0?'none':'');al.setAttribute('x',mx-10*dy/len);al.setAttribute('y',my+10*dx/len);al.textContent='a=6'}const mark=root.querySelector('[data-feasible-right]');if(g.tangent&&g.roots.length){const t=g.roots[0],[x,y]=feasiblePoint(b,t,g),ux=Math.cos(g.A),uy=-Math.sin(g.A),vx=(cx-x)/6/g.scale,vy=(ay-y)/6/g.scale,size=11;mark.setAttribute('d',`M ${x-ux*size} ${y-uy*size} l ${vx*size} ${vy*size} l ${ux*size} ${uy*size}`);mark.setAttribute('display','')}else mark.setAttribute('display','none');return g}
function sectionHeader(s,introEn,introId){return `<div class="teacher-banner ${state.teacher?'show':''}"><span>${t('teacherOn')}</span><button data-teacher-complete>${L('Mark this section complete','Tandai bagian ini selesai')}</button></div><div class="section-head"><div><span class="kicker">${L('UNIT','UNIT')} ${s.id}</span><h2>${secTitle(s)}</h2><p>${L(introEn,introId)}</p></div><div class="unit-badge">${s.id}</div></div><div class="learning-cycle"><span class="cycle-chip">${L('notice','amati')}</span><span class="cycle-chip">${L('explore','jelajahi')}</span><span class="cycle-chip">${L('formalize','formalkan')}</span><span class="cycle-chip">${L('guided example','contoh terbimbing')}</span><span class="cycle-chip">${L('your turn','giliranmu')}</span></div>`}
function academicBridge(titleEn,titleId,items){const key=state.current;const index=Math.max(0,Math.min(items.length-1,Number(state.bridgeSteps?.[key])||0));const shortText=value=>{const m=String(value).match(/^.{1,260}?[.!?](?=\s|$)/);return m?m[0]:value};const panels=items.map((item,i)=>{const full=L(item[2],item[3]),short=shortText(full),deep=full.length>short.length?`<details class="bridge-deep"><summary>${L('Why does this work? · Formal reasoning','Mengapa ini berlaku? · Penalaran formal')}</summary><p>${full.slice(short.length).trim()}</p></details>`:'';return `<article class="bridge-panel" ${i===index?'':'hidden'}><h4>${L(item[0],item[1])}</h4><p>${short}</p>${deep}</article>`}).join('');return `<section class="scene academic-bridge" data-bridge-stepper data-bridge-index="${index}" data-bridge-count="${items.length}"><div class="bridge-heading"><div><div class="scene-label">${L('BUILD THE IDEA','BANGUN PEMAHAMANNYA')} · <span data-bridge-counter aria-live="polite" aria-atomic="true">${index+1}/${items.length}</span></div><h3>${L(titleEn,titleId)}</h3></div><div class="bridge-controls"><button type="button" data-bridge-prev ${index===0?'disabled':''} aria-label="${L('Previous idea','Gagasan sebelumnya')}">←</button><button type="button" data-bridge-next ${index===items.length-1?'disabled':''}>${L('Next idea','Gagasan berikutnya')} →</button></div></div><div class="bridge-stage">${panels}</div></section>`}
function itemsFromStepper(box){return [...box.querySelectorAll('.bridge-panel')]}
function completePanel(id){const done=state.completed.includes(id);return `<div class="complete-panel"><div><strong>${done?t('completed'):L('Ready to continue?','Siap melanjutkan?')}</strong><div>${done?L('This section is already recorded as complete.','Bagian ini sudah tercatat selesai.'):L('Mark complete when the main idea feels secure.','Tandai selesai setelah ide utamanya terasa cukup kuat.')}</div></div><button data-complete="${id}">${done?t('completed'):t('complete')}</button></div>`}
function home(){const cards=sections.map((s,i)=>`<button class="topic-card ${isOpen(s.id)?'':'locked'}" data-goto="${s.id}"><span class="unit">${s.id}</span><strong>${secTitle(s)}</strong><p>${secSub(s)}</p></button>`).join('');return `<section class="hero"><div class="hero-copy"><span class="kicker">GEOMETRY 5 · ${L('CAMBRIDGE-ALIGNED GRADE 11','SELARAS CAMBRIDGE KELAS 11')}</span><h1>${L('Read the geometry first, then choose the trigonometry.','Baca geometrinya dulu, baru pilih trigonometrinya.')}</h1><p class="lead">${L('A strong solver does not hunt for a familiar formula. They locate the target, identify the triangle that contains it, connect any missing geometry, then calculate and verify.','Pemecah soal yang kuat tidak berburu rumus yang terlihat familiar. Ia menentukan target, menemukan segitiga yang memuat target, melengkapi geometri yang masih kurang, lalu menghitung dan memeriksa hasil.')}</p><div class="home-path"><span class="path-pill">${L('Diagram','Diagram')}</span><span>→</span><span class="path-pill">${L('Known information','Informasi diketahui')}</span><span>→</span><span class="path-pill">${L('Target','Target')}</span><span>→</span><span class="path-pill">${L('Triangle structure','Struktur segitiga')}</span><span>→</span><span class="path-pill">${L('Method','Metode')}</span><span>→</span><span class="path-pill">${L('Check','Cek')}</span></div><div class="hero-actions"><button class="primary-action" data-goto="A">${L('Start the lesson','Mulai pelajaran')}</button><button class="secondary-action" data-goto="S">${L('Open decision summary','Buka ringkasan keputusan')}</button></div></div><div class="mascot-stage"><div class="mascot-halo"></div><img src="${MASCOT}sheet1_bottom_01.png" alt=""><div class="speech">${L('Which triangle actually contains the quantity you need?','Segitiga mana yang sebenarnya memuat besaran yang kamu cari?')}</div></div></section><section class="scene"><div class="scene-label">${L('TOPIC MAP','PETA TOPIK')}</div><h2>${L('From retrieval to multi-stage trigonometric geometry','Dari pengingat dasar hingga geometri trigonometri bertahap')}</h2><div class="topic-grid">${cards}</div></section>`}
function unitA(){const s=sections[0];return sectionHeader(s,'Keep this diagnostic short. The goal is to expose weak retrieval before it interferes with non-right-triangle work.','Buat diagnosis ini singkat. Tujuannya menemukan kelemahan dasar sebelum mengganggu pembahasan segitiga non-siku-siku.')+academicBridge("Start with the triangle, not the chapter title","Mulai dari segitiganya, bukan judul bab",[["What must be established first?","Apa yang perlu dipastikan lebih dulu?","Pythagoras and the ratios sin, cos, tan apply only after a right angle is known or proved. A perspective sketch can suggest a right angle, but appearance alone is not evidence.","Teorema Pythagoras dan rasio sin, cos, tan hanya berlaku setelah sudut siku-siku diketahui atau dibuktikan. Sketsa perspektif bisa tampak siku-siku, tetapi tampilannya saja bukan bukti."],["Choose by the target","Pilih berdasarkan target","If two perpendicular sides are known and the hypotenuse is wanted, use Pythagoras. If an angle or side is wanted, label the reference angle first: opposite is across from it, adjacent touches it (but is not the hypotenuse), and hypotenuse is opposite the right angle.","Jika dua sisi tegak lurus diketahui dan yang dicari sisi miring, gunakan Pythagoras. Jika yang dicari sudut atau sisi, tandai dulu sudut acuannya: sisi depan berada di seberangnya, sisi samping menyentuh sudut itu (tetapi bukan sisi miring), dan sisi miring berhadapan dengan sudut siku-siku."],["What each ratio compares","Perbandingan pada tiap rasio","sin θ = opposite/hypotenuse; cos θ = adjacent/hypotenuse; tan θ = opposite/adjacent. Each is a ratio of lengths in the same right triangle. Check that the chosen sides really match θ before substituting.","sin θ = depan/miring; cos θ = samping/miring; tan θ = depan/samping. Masing-masing membandingkan panjang sisi pada segitiga siku-siku yang sama. Pastikan sisi yang dipilih memang sesuai dengan θ sebelum memasukkan nilai."],["A quick sense check","Pemeriksaan cepat","The hypotenuse must be the longest side. For an acute θ, sin θ and cos θ lie between 0 and 1. If a calculation contradicts these facts, revisit the labels, angle mode, and right-angle justification.","Sisi miring harus menjadi sisi terpanjang. Untuk θ lancip, nilai sin θ dan cos θ berada di antara 0 dan 1. Jika hasil bertentangan dengan fakta ini, periksa kembali label, mode kalkulator, dan alasan sudut siku-siku."]])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('DIAGNOSTIC','DIAGNOSIS')}</div><div class="big-question">${L('Is trigonometry really the simplest tool here?','Apakah trigonometri benar-benar alat paling sederhana di sini?')}</div><p>${L('Right-triangle ratios remain active tools, but Pythagoras may be simpler when two legs are known. A diagram that only looks square is not enough: the right angle must be given or proved.','Perbandingan trigonometri segitiga siku-siku tetap menjadi alat penting, tetapi Teorema Pythagoras bisa lebih sederhana ketika dua kaki diketahui. Gambar yang tampak siku-siku saja tidak cukup: sudut siku-sikunya harus diberikan atau dibuktikan.')}</p>${mascot('sheet1_top_04.png',L('A trigonometry chapter does not mean trigonometry should always be used.','Bab trigonometri bukan berarti setiap soal harus diselesaikan dengan trigonometri.'))}</div><div class="visual-panel">${triangleSvg({A:[123,230],B:[206.3,230],C:[123,30],right:true,sideLabels:{AB:'5',AC:'12',BC:'?'}})}<div class="visual-caption">${L('If the two perpendicular legs are known, Pythagoras is the cleanest route to the hypotenuse.','Jika kedua kaki siku-siku diketahui, Pythagoras adalah jalur paling langsung menuju sisi miring.')}</div></div></section><section class="scene">${guided('Right-triangle retrieval','Pengingat segitiga siku-siku','A right triangle has adjacent side 5 cm and hypotenuse 13 cm. Find θ.','Sebuah segitiga siku-siku memiliki sisi samping 5 cm dan sisi miring 13 cm. Tentukan θ.','core',['The ratio involving adjacent and hypotenuse is cosine.','cos θ = 5/13.','θ = cos⁻¹(5/13) ≈ 67.4°.'],['Perbandingan yang melibatkan sisi samping dan sisi miring adalah cosinus.','cos θ = 5/13.','θ = cos⁻¹(5/13) ≈ 67,4°.'])}</section>${completePanel('A')}`}
function unitB(){const s=sections[1];return sectionHeader(s,'Before calculating, classify what the triangle actually gives you.','Sebelum menghitung, klasifikasikan informasi yang benar-benar diberikan oleh segitiga.')+academicBridge("A method becomes available from a structure","Metode tersedia karena struktur segitiganya",[["Name the information pattern","Kenali pola informasinya","SAS means two sides and their included angle; SSS means three sides; ASA/AAS means two angles and a side; SSA means a side, a non-included angle, and another side. “Included” means the angle lies between the two named sides.","SAS berarti dua sisi dan sudut apitnya; SSS berarti tiga sisi; ASA/AAS berarti dua sudut dan satu sisi; SSA berarti satu sisi, sudut yang bukan sudut apit, dan sisi lain. “Apit” berarti sudut berada di antara dua sisi yang disebut."],["Ask what is still missing","Tanyakan apa yang belum diketahui","A formula is useful only when its required relationship is present. A complete opposite side–angle pair unlocks the sine rule. SAS gives the cosine rule for the third side; SSS gives it for an angle. Two known angles may first require the angle sum to create a paired angle.","Rumus berguna jika hubungan yang dibutuhkan memang tersedia. Pasangan sisi-sudut berhadapan yang lengkap memungkinkan aturan sinus. Pola SAS memberi akses ke aturan cosinus untuk sisi ketiga; SSS untuk mencari sudut. Dua sudut yang diketahui mungkin perlu dijumlahkan dulu untuk memperoleh sudut pasangan."],["Pre-process before selecting","Olah informasi sebelum memilih","The first operation may be angle sum, Pythagoras, similarity, or a smaller gateway triangle. Only then may the target triangle contain enough information for sine or cosine rule. Separate method identification from substitution, algebra, and geometric validation.","Langkah pertama bisa berupa jumlah sudut, Pythagoras, kesebangunan, atau segitiga penghubung yang lebih kecil. Setelah itu barulah segitiga target mungkin memiliki informasi yang cukup untuk aturan sinus atau cosinus. Bedakan pemilihan metode dari substitusi, penyelesaian aljabar, dan pemeriksaan geometri."]])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('METHOD EXPLORER','PENJELAJAH METODE')}</div><div class="big-question">${L('What becomes available from this information pattern?','Metode apa yang menjadi tersedia dari pola informasi ini?')}</div><ol><li>${L('Which triangle contains the target?','Segitiga mana yang memuat target?')}</li><li>${L('What is already known inside it?','Apa yang sudah diketahui di dalamnya?')}</li><li>${L('Can simpler geometry produce one more useful side or angle?','Bisakah geometri yang lebih sederhana menghasilkan satu sisi atau sudut tambahan?')}</li><li>${L('Which method is available now?','Metode apa yang sekarang dapat digunakan?')}</li></ol>${mascot('sheet2_top_02.png',L('Choose from the structure, not from a keyword.','Pilih metode dari strukturnya, bukan dari kata kunci.'))}</div><div class="visual-panel"><p class="explorer-instruction">${L('Explore any scenario: each button is a valid information pattern, not a one-answer quiz.','Jelajahi skenario mana saja: setiap tombol adalah pola informasi yang valid, bukan kuis dengan satu jawaban.')}</p><div class="method-grid" id="methodLab">${[['Right triangle: legs 5 and 12; find hypotenuse','Segitiga siku-siku: kaki 5 dan 12; cari hipotenusa','Pythagoras'],['Angles 42° and 73°, a=8; find b and c','Sudut 42° dan 73°, a=8; cari b dan c','Angle sum → sine rule'],['Sides 7 and 10 with included angle 54°','Sisi 7 dan 10 dengan sudut apit 54°','Cosine rule / area'],['Sides 8, 11, 13; find angle opposite 13','Sisi 8, 11, 13; cari sudut di depan 13','Cosine rule'],['Known opposite pair; find another pair','Pasangan berhadapan diketahui; cari pasangan lain','Sine rule'],['Target triangle lacks a shared diagonal','Segitiga target kekurangan diagonal bersama','Gateway quantity first']].map((x,i)=>`<button class="method-btn" data-method-option="${i}"><span>${L(x[0],x[1])}</span><small>${L('Explore this structure','Jelajahi struktur ini')}</small></button>`).join('')}</div><div class="quiz-feedback" id="methodFeedback"></div></div></section><section class="scene"><div class="toolkit"><div class="tool-row"><strong>${L('Right triangle','Segitiga siku-siku')}</strong><br>${L('Pythagoras or sin/cos/tan','Pythagoras atau sin/cos/tan')}</div><div class="tool-row"><strong>${L('ASA/AAS','ASA/AAS')}</strong><br>${L('Angle sum → sine rule','Jumlah sudut → aturan sinus')}</div><div class="tool-row"><strong>${L('SAS','SAS')}</strong><br>${L('Cosine rule for side; ½ab sin C for area','Aturan cosinus untuk sisi; ½ab sin C untuk luas')}</div><div class="tool-row"><strong>${L('SSS','SSS')}</strong><br>${L('Cosine rule for angle','Aturan cosinus untuk sudut')}</div><div class="tool-row"><strong>${L('Known opposite pair','Pasangan berhadapan lengkap')}</strong><br>${L('Sine rule','Aturan sinus')}</div><div class="tool-row"><strong>${L('Not enough yet','Belum cukup informasi')}</strong><br>${L('Find a gateway side/angle first','Cari dulu sisi/sudut penghubung')}</div></div></section>${completePanel('B')}`}
function unitC(){const s=sections[2];return sectionHeader(s,'The sine rule depends on opposite side-angle pairing. Build the pairing before writing fractions.','Aturan sinus bergantung pada pasangan sisi dan sudut yang saling berhadapan. Bentuk pasangannya sebelum menulis pecahan.')+academicBridge("Why opposite pairs matter","Mengapa pasangan sisi-sudut berhadapan penting",[["Pair before writing","Pasangkan sebelum menulis","In △ABC, side a is opposite angle A, b opposite B, and c opposite C. The sine rule compares matching pairs only; writing a/sin B is a mismatch. Mark the opposite relationship on the diagram before forming an equation.","Pada △ABC, sisi a berhadapan dengan sudut A, b dengan B, dan c dengan C. Aturan sinus hanya membandingkan pasangan yang cocok; a/sin B adalah pasangan yang salah. Tandai hubungan berhadapan pada diagram sebelum membentuk persamaan."],["Two equivalent forms","Dua bentuk yang setara","a/sin A = b/sin B = c/sin C and sin A/a = sin B/b = sin C/c say the same thing. Use the first when finding a side from a known pair; the second may be convenient when the unknown is an angle or when comparing ratios.","a/sin A = b/sin B = c/sin C dan sin A/a = sin B/b = sin C/c menyatakan hal yang sama. Bentuk pertama sering praktis untuk mencari sisi dari pasangan yang diketahui; bentuk kedua bisa nyaman ketika mencari sudut atau membandingkan rasio."],["Why the relation holds","Mengapa hubungan ini berlaku","The area can be written using each included angle: K = ½bc sin A = ½ca sin B = ½ab sin C. Dividing these equal expressions by the common positive quantity ½abc gives sin A/a = sin B/b = sin C/c. Taking reciprocals gives the other form.","Luas dapat ditulis menggunakan masing-masing sudut: K = ½bc sin A = ½ca sin B = ½ab sin C. Membagi persamaan yang sama ini dengan besaran positif ½abc menghasilkan sin A/a = sin B/b = sin C/c. Mengambil kebalikan menghasilkan bentuk lainnya."],["When it applies and how to check","Kapan digunakan dan cara memeriksa","Use it when at least one complete opposite pair is known and another paired quantity is sought. In a triangle, the larger angle must face the longer side; use this as a plausibility check after calculating.","Gunakan ketika setidaknya satu pasangan berhadapan lengkap diketahui dan pasangan lain dicari. Dalam segitiga, sudut lebih besar berhadapan dengan sisi lebih panjang; gunakan ini untuk memeriksa kewajaran hasil."]])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('WHY IT WORKS','MENGAPA INI BEKERJA')}</div><div class="big-question">${L('Which side belongs with which angle?','Sisi mana berpasangan dengan sudut mana?')}</div><div class="formula-flow"><div class="formula">a / sin A = b / sin B = c / sin C</div><div class="reason-note">${L('The same triangle area can be written as ½bc sin A = ½ca sin B = ½ab sin C. Dividing by ½abc produces the reciprocal sine-rule form.','Luas segitiga yang sama dapat ditulis sebagai ½bc sin A = ½ca sin B = ½ab sin C. Membagi dengan ½abc menghasilkan bentuk kebalikan aturan sinus.')}</div></div></div><div class="visual-panel triangle-stage" id="pairMapper">${trianglePairSvg()}<div class="pair-controls"><button data-pair="a" class="active">a ↔ A</button><button data-pair="b">b ↔ B</button><button data-pair="c">c ↔ C</button></div><div class="diagram-note" id="pairNote">${L('Side a is opposite angle A.','Sisi a berada di depan sudut A.')}</div></div></section><section class="scene">${guided('Missing sides','Mencari sisi','In △ABC, A = 42°, B = 73°, a = 8 cm. Find b and c.','Pada △ABC, A = 42°, B = 73°, a = 8 cm. Tentukan b dan c.','core',['First find C = 180° − 42° − 73° = 65°.','The known opposite pair is (A,a).','b/sin73° = 8/sin42° → b ≈ 11.4 cm.','c/sin65° = 8/sin42° → c ≈ 10.8 cm. The largest angle has the largest opposite side, so the result is plausible.'],['Cari dahulu C = 180° − 42° − 73° = 65°.','Pasangan berhadapan yang lengkap adalah (A,a).','b/sin73° = 8/sin42° → b ≈ 11,4 cm.','c/sin65° = 8/sin42° → c ≈ 10,8 cm. Sudut terbesar memiliki sisi di depannya yang paling panjang, sehingga hasil ini masuk akal.'])}</section>${practiceHTML('C')}${completePanel('C')}`}
function unitD(){const s=sections[3];return sectionHeader(s,'Inverse sine may hide a supplementary angle. A calculator gives a candidate; the triangle decides whether it survives.','Invers sinus dapat menyembunyikan sudut suplementer. Kalkulator memberi kandidat; segitiga menentukan apakah kandidat itu tetap valid.')+academicBridge("The second angle is a real geometric possibility","Sudut kedua adalah kemungkinan geometri yang nyata",[["Why inverse sine returns a candidate","Mengapa invers sinus memberi kandidat","For an acute value θ, sin θ = sin(180°−θ). A calculator’s sin⁻¹ usually returns only the principal acute candidate. The same height in an SSA construction can meet the fixed ray in two positions, giving supplementary angles and two different triangles.","Untuk θ lancip, sin θ = sin(180°−θ). Fungsi sin⁻¹ pada kalkulator biasanya hanya memberi kandidat utama yang lancip. Pada konstruksi SSA, panjang yang sama dapat memotong sinar tetap di dua posisi, menghasilkan sudut suplementer dan dua segitiga berbeda."],["Test each candidate in the whole triangle","Uji setiap kandidat pada segitiga utuh","If B₁ = sin⁻¹(value), the alternative is B₂ = 180°−B₁. Each candidate must leave a positive third angle: A + B < 180°. A candidate also must match the given side lengths and the stated location/order of points.","Jika B₁ = sin⁻¹(nilai), alternatifnya B₂ = 180°−B₁. Setiap kandidat harus menyisakan sudut ketiga yang positif: A + B < 180°. Kandidat juga harus cocok dengan panjang sisi yang diberikan serta letak/urutan titik dalam soal."],["Zero, one, or two valid triangles","Nol, satu, atau dua segitiga yang valid","The inverse-sine output is algebraic, not yet a proof of a valid triangle. Reject impossible candidates; keep both only when each satisfies all angle and length constraints. This is the distinction between solving an equation and validating a geometric configuration.","Hasil invers sinus adalah kandidat aljabar, belum bukti bahwa segitiganya valid. Tolak kandidat yang mustahil; terima keduanya hanya jika masing-masing memenuhi semua batas sudut dan panjang. Inilah perbedaan antara menyelesaikan persamaan dan memvalidasi konfigurasi geometri."]])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('0 / 1 / 2 CONFIGURATIONS','0 / 1 / 2 KONFIGURASI')}</div><div class="big-question">${L('Could the same length reach the ray in more than one place?','Bisakah panjang yang sama mencapai sinar di lebih dari satu posisi?')}</div><p>${L('Because sin θ = sin(180°−θ), an SSA problem may have two valid triangles. The second configuration must not be accepted automatically: check the remaining angle and the geometry.','Karena sin θ = sin(180°−θ), soal SSA dapat memiliki dua segitiga valid. Konfigurasi kedua tidak boleh langsung diterima: cek sudut yang tersisa dan geometrinya.')}</p><div class="formula-flow"><div class="formula">B₂ = 180° − B₁</div><div class="reason-note">${L('Then test whether A + B₂ < 180°.','Lalu cek apakah A + B₂ < 180°.')}</div></div>${mascot('sheet2_bottom_04.png',L('The second triangle is not shown in the initial problem visual — discovering it is part of the reasoning.','Segitiga kedua tidak ditampilkan pada visual soal awal — menemukannya adalah bagian dari penalaran.'))}</div><div class="visual-panel">${ambiguousSvg(!!state.ambigRevealed)}<div class="status-row"><button class="mini-choice" data-ambig-reveal>${L('Reveal the supplementary candidate after reasoning','Tampilkan kandidat suplementer setelah bernalar')}</button></div><div class="diagram-note" id="ambigNote">${L('Initial state: givens and construction structure only.','Keadaan awal: hanya informasi diketahui dan struktur konstruksi.')}</div></div></section><section class="scene">${guided('Two possible triangles','Dua kemungkinan segitiga','A = 35°, a = 8, b = 11. Find all possible B.','A = 35°, a = 8, b = 11. Tentukan semua kemungkinan B.','challenge',['Use sin B = 11 sin35° / 8 ≈ 0.788668.','First candidate: B₁ ≈ 52.1°.','Supplementary candidate: B₂ ≈ 127.9°.','Both leave a positive third angle, so both triangles are valid.'],['Gunakan sin B = 11 sin35° / 8 ≈ 0,788668.','Kandidat pertama: B₁ ≈ 52,1°.','Kandidat suplementer: B₂ ≈ 127,9°.','Keduanya menyisakan sudut ketiga yang positif, sehingga kedua segitiga valid.'])}</section>${practiceHTML('D')}${completePanel('D')}`}
function unitE(){const s=sections[4],storedAngle=Number(state.cosAngle),angle=Math.max(25,Math.min(150,Number.isFinite(storedAngle)?storedAngle:54)),x=Math.sqrt(7*7+10*10-2*7*10*Math.cos(angle*Math.PI/180));return sectionHeader(s,'Keep sides a=7 and b=10 fixed. Predict what changing their included angle C will do to the opposite side c, then test the prediction.','Pertahankan sisi a=7 dan b=10. Prediksi dampak perubahan sudut apit C terhadap sisi di depannya c, lalu uji prediksimu.')+`<section class="scene prediction-strip"><div><div class="scene-label">${L('PREDICT FIRST','PREDIKSI DULU')}</div><p>${L('As C opens from acute through 90° to obtuse, what should happen to c? Keep a and b fixed.','Saat C berubah dari lancip melewati 90° menjadi tumpul, apa yang terjadi pada c? Pertahankan a dan b.')}</p></div></section><section class="scene focus-grid cosine-discovery"><div class="visual-panel" id="cosExplorer">${cosineExplorerSvg(angle)}<div class="control-row"><label for="cosAngleRange">${L('Included angle C','Sudut apit C')}</label><input id="cosAngleRange" type="range" min="25" max="150" value="${angle}" step="1" data-cos-range aria-valuemin="25" aria-valuemax="150" aria-valuenow="${angle}"><span class="metric" data-cos-angle>${angle}°</span></div><div class="diagram-note" data-cos-note>${cosineCaseNote(angle,x)}</div></div><div class="concept-copy"><div class="scene-label">${L('OBSERVE','AMATI')}</div><div class="big-question">${L('The vertex moves, so the opposite side changes.','Titik sudut bergerak, sehingga sisi di depannya berubah.')}</div><p>${L('The visual holds a=7 and b=10 fixed. The angle arc and vertex move together; the side opposite C is recomputed from the same triangle.','Visual mempertahankan a=7 dan b=10. Busur sudut dan titik sudut bergerak bersama; sisi di depan C dihitung ulang dari segitiga yang sama.')}</p><div class="formula-flow"><div class="formula">c² = a² + b² − 2ab cos C</div><div class="reason-note">${L('At 90°, cos C=0 and c²=a²+b²: the Pythagorean case.','Pada 90°, cos C=0 dan c²=a²+b²: kasus Pythagoras.')}</div></div><div class="cos-rule-tabs" role="group" aria-label="${L('Cosine rule use cases','Penerapan aturan cosinus')}"><button type="button" data-cos-use="sas" aria-pressed="${state.cosUse!=='sss'}">SAS → ${L('find a side','cari sisi')}</button><button type="button" data-cos-use="sss" aria-pressed="${state.cosUse==='sss'}">SSS → ${L('find an angle','cari sudut')}</button></div><div class="cos-use-panel" data-cos-use-panel="sas" ${state.cosUse==='sss'?'hidden':''}><strong>SAS</strong><p>${L('Two sides and their included angle determine the third side.','Dua sisi dan sudut apitnya menentukan sisi ketiga.')}</p><div class="formula">c²=a²+b²−2ab cos C</div></div><div class="cos-use-panel" data-cos-use-panel="sss" ${state.cosUse==='sss'?'':'hidden'}><strong>SSS</strong><p>${L('Three sides determine an angle by rearranging the same relationship.','Tiga sisi menentukan sudut dengan menyusun ulang hubungan yang sama.')}</p><div class="formula">cos C=(a²+b²−c²)/(2ab)</div></div></div></section><section class="scene">${guided('SAS → third side','SAS → sisi ketiga','Two sides are 7 cm and 10 cm with included angle 54°. Find the third side.','Dua sisi panjangnya 7 cm dan 10 cm dengan sudut apit 54°. Tentukan sisi ketiga.','core',['This is SAS, so cosine rule is the natural first method.','x² = 7² + 10² − 2(7)(10)cos54°.','x ≈ 8.17 cm.'],['Ini adalah SAS, jadi aturan cosinus adalah metode pertama yang paling alami.','x² = 7² + 10² − 2(7)(10)cos54°.','x ≈ 8,17 cm.'])}${guided('SSS → angle','SSS → sudut','A triangle has sides 8, 11 and 13. Find the angle opposite side 13.','Sebuah segitiga memiliki sisi 8, 11, dan 13. Tentukan sudut di depan sisi 13.','challenge',['All three sides are known, so rearrange the cosine rule for the angle.','cos C = (8² + 11² − 13²)/(2·8·11).','C ≈ 84.8°.'],['Ketiga sisi diketahui, jadi susun ulang aturan cosinus untuk mencari sudut.','cos C = (8² + 11² − 13²)/(2·8·11).','C ≈ 84,8°'])}</section>${practiceHTML('E')}${completePanel('E')}`}

function unitF(){const s=sections[5];return sectionHeader(s,'A harder-looking problem is often asking for simpler geometry before any sine or cosine rule becomes available.','Soal yang tampak lebih sulit sering meminta geometri yang lebih sederhana sebelum aturan sinus atau cosinus dapat digunakan.')+academicBridge("A strategic checkpoint after both rules","Titik pemeriksaan strategi setelah mempelajari kedua aturan",[["First simplify the geometry","Sederhanakan geometri terlebih dahulu","Before choosing sine or cosine rule, inspect the whole diagram. Angle sum may reveal a missing angle; Pythagoras may complete a right triangle; similarity may transfer a ratio. These are not detours: they create the information pattern a later method needs.","Sebelum memilih aturan sinus atau cosinus, periksa seluruh diagram. Jumlah sudut dapat memberi sudut yang hilang; Pythagoras dapat melengkapi segitiga siku-siku; kesebangunan dapat memindahkan rasio. Ini bukan jalan memutar: langkah-langkah tersebut menciptakan pola informasi yang dibutuhkan metode berikutnya."],["Then identify the gateway quantity","Lalu tentukan besaran penghubung","If the target triangle is still under-specified, ask what single side, angle, perpendicular, or diagonal would unlock it. Find that gateway in the smaller triangle or known structure, then return to the target.","Jika informasi pada segitiga target masih kurang, tanyakan sisi, sudut, garis tegak lurus, atau diagonal apa yang akan melengkapinya. Cari besaran penghubung itu pada segitiga kecil atau struktur yang sudah diketahui, lalu kembali ke target."],["Now choose and validate","Baru pilih metode dan validasi","A complete opposite pair points to sine rule; SAS/SSS points to cosine rule; two sides with their included angle can give area. After calculation, check angle sum, side-angle order, units, and whether the result fits the diagram.","Pasangan berhadapan lengkap mengarah ke aturan sinus; SAS/SSS ke aturan cosinus; dua sisi beserta sudut apitnya dapat memberi luas. Setelah menghitung, cek jumlah sudut, urutan sisi-sudut, satuan, dan kecocokan hasil dengan diagram."]])+`<section class="scene"><div class="scene-label">${L('DO NOT FORCE A RULE','JANGAN MEMAKSAKAN ATURAN')}</div><h3>${L('Structure → best first thought','Struktur → ide pertama yang paling tepat')}</h3><div class="toolkit"><div class="tool-row"><strong>${L('Two angles + one side','Dua sudut + satu sisi')}</strong><p>${L('Angle sum, then sine rule.','Jumlah sudut, lalu aturan sinus.')}</p></div><div class="tool-row"><strong>${L('Two sides + included angle','Dua sisi + sudut apit')}</strong><p>${L('Cosine rule, or area formula if area is the target.','Aturan cosinus, atau rumus luas jika targetnya luas.')}</p></div><div class="tool-row"><strong>${L('Three sides','Tiga sisi')}</strong><p>${L('Cosine rule for an angle.','Aturan cosinus untuk mencari sudut.')}</p></div><div class="tool-row"><strong>${L('Right triangle','Segitiga siku-siku')}</strong><p>${L('Pythagoras/basic trig.','Pythagoras/trigonometri dasar.')}</p></div><div class="tool-row"><strong>${L('Similar figures','Bangun sebangun')}</strong><p>${L('Similarity before trigonometry.','Kesebangunan sebelum trigonometri.')}</p></div><div class="tool-row"><strong>${L('Target triangle cannot yet be solved','Segitiga target belum bisa diselesaikan')}</strong><p>${L('Find a gateway angle, side, perpendicular or diagonal first.','Cari dulu sudut, sisi, garis tegak lurus, atau diagonal penghubung.')}</p></div></div>${mascot('sheet1_bottom_03.png',L('If neither rule works immediately, that is information — the geometry is asking you to connect something first.','Jika kedua aturan belum bisa langsung dipakai, itu adalah petunjuk — geometrinya meminta kamu menghubungkan sesuatu terlebih dahulu.'))}</section>${completePanel('F')}`}
function unitG(){const s=sections[6];return sectionHeader(s,'Build the trigonometric area formula from base × height, then use it in both directions.','Bangun rumus luas trigonometri dari alas × tinggi, lalu gunakan dalam dua arah.')+academicBridge("Derive the area relationship from height","Turunkan hubungan luas dari tinggi",[["Fix the notation","Tetapkan notasinya","In △ABC, let a = BC, b = CA, and c = AB; capital letters name the opposite angles. Choose sides a and b meeting at angle C. Drop a perpendicular from A to BC and call its height h.","Pada △ABC, misalkan a = BC, b = CA, dan c = AB; huruf besar menamai sudut yang berhadapan. Pilih sisi a dan b yang bertemu di sudut C. Tarik garis tegak lurus dari A ke BC dan sebut tingginya h."],["The height is the missing link","Tinggi adalah penghubungnya","In the right triangle formed by the altitude, b is the hypotenuse and angle C is between b and the base direction. Thus sin C = h/b, so h = b sin C. Substituting into K = ½ × base × height = ½ah gives K = ½ab sin C.","Pada segitiga siku-siku yang terbentuk oleh garis tinggi, b adalah sisi miring dan sudut C berada antara b dan arah alas. Maka sin C = h/b, sehingga h = b sin C. Substitusi ke K = ½ × alas × tinggi = ½ah menghasilkan K = ½ab sin C."],["Choose the included angle carefully","Pilih sudut apit dengan cermat","The angle must lie between the two side lengths used. The equivalent forms are K = ½bc sin A and K = ½ca sin B. Do not pair a and b with angle A: A is not their included angle.","Sudutnya harus berada di antara dua panjang sisi yang digunakan. Bentuk setaranya adalah K = ½bc sin A dan K = ½ca sin B. Jangan memasangkan a dan b dengan sudut A: A bukan sudut apit keduanya."],["Reverse area and ambiguity","Mencari sudut dari luas dan kemungkinan ganda","If K, a, and b are known, sin C = 2K/(ab). Since sine is equal for supplementary angles, the equation may produce C or 180°−C. Check whether both fit the triangle and any other given information. Also K must be at most ½ab.","Jika K, a, dan b diketahui, sin C = 2K/(ab). Karena nilai sinus sama untuk sudut suplementer, persamaan dapat menghasilkan C atau 180°−C. Periksa apakah keduanya cocok dengan segitiga dan informasi lain. Selain itu, K tidak boleh melebihi ½ab."]])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('WHY IT WORKS','MENGAPA INI BEKERJA')}</div><div class="big-question">${L('Where does sin C come from in the area formula?','Dari mana sin C muncul pada rumus luas?')}</div><p>${L('If side b makes included angle C with base a, the perpendicular height is b sin C. Substituting into ½(base)(height) gives the formula.','Jika sisi b membentuk sudut apit C dengan alas a, tinggi tegak lurusnya adalah b sin C. Substitusi ke ½(alas)(tinggi) menghasilkan rumus.')}</p><div class="formula-flow"><div class="formula">A = ½ab sin C</div><div class="reason-note">${L('C must be the included angle between the two chosen sides.','C harus merupakan sudut apit antara dua sisi yang dipilih.')}</div></div></div><div class="visual-panel">${areaTriangleSvg()}<div class="visual-caption">${L('The altitude is a structural helper; its numerical value is not shown in the problem state.','Garis tinggi adalah bantuan struktur; nilai numeriknya tidak ditampilkan pada keadaan soal.')}</div></div></section><section class="scene">${guided('Direct area','Luas langsung','Two sides are 9 cm and 13 cm with included angle 38°. Find the area.','Dua sisi panjangnya 9 cm dan 13 cm dengan sudut apit 38°. Tentukan luasnya.','core',['Use the included-angle area formula.','A = ½(9)(13)sin38°.','A ≈ 36.0 cm².'],['Gunakan rumus luas dengan sudut apit.','A = ½(9)(13)sin38°.','A ≈ 36,0 cm².'])}${guided('Reverse area','Luas terbalik','Area = 30, a = 8, b = 10. Find all possible included angles C.','Luas = 30, a = 8, b = 10. Tentukan semua kemungkinan sudut apit C.','challenge',['30 = ½(8)(10)sin C, so sin C = 3/4.','First candidate C ≈ 48.6°.','Supplementary candidate C ≈ 131.4°. Both have the same sine and both are valid included angles.'],['30 = ½(8)(10)sin C, sehingga sin C = 3/4.','Kandidat pertama C ≈ 48,6°.','Kandidat suplementer C ≈ 131,4°. Keduanya memiliki nilai sinus yang sama dan keduanya valid sebagai sudut apit.'])}</section>${practiceHTML('G')}${completePanel('G')}`}
function unitH(){const s=sections[7],storedBeta=Number(state.bearing),beta=Math.max(0,Math.min(359,Number.isFinite(storedBeta)?storedBeta:40));const E=18*Math.sin(beta*Math.PI/180),N=18*Math.cos(beta*Math.PI/180);return sectionHeader(s,'Bearings are measured clockwise from North. Convert them into internal triangle angles or east-north components before calculating.','Bearing diukur searah jarum jam dari Utara. Ubah menjadi sudut dalam segitiga atau komponen timur-utara sebelum menghitung.')+academicBridge("Read a bearing as a direction before making a triangle","Baca bearing sebagai arah sebelum membentuk segitiga",[["The three-figure convention","Konvensi tiga angka","A bearing is written with three digits and measured clockwise from North: 000° is North, 090° East, 180° South, and 270° West. At each point, draw a North line first; measure the turn clockwise from that line.","Bearing ditulis dengan tiga angka dan diukur searah jarum jam dari Utara: 000° adalah Utara, 090° Timur, 180° Selatan, dan 270° Barat. Di setiap titik, gambar garis Utara terlebih dahulu; ukur putaran searah jarum jam dari garis itu."],["Turn bearings into an internal angle","Ubah bearing menjadi sudut dalam","A triangle’s interior angle is measured between its two sides, not from North. At a turning point, reverse the incoming direction by adding or subtracting 180° to get the back bearing, then compare it with the outgoing bearing. The smaller separation may be the internal angle; state which angle is required.","Sudut dalam segitiga diukur di antara dua sisinya, bukan dari Utara. Di titik belok, balikkan arah perjalanan sebelumnya dengan menambah atau mengurangi 180° untuk memperoleh back bearing, lalu bandingkan dengan bearing arah keluar. Selisih yang lebih kecil dapat menjadi sudut dalam; pastikan sudut mana yang diminta."],["Components are measured from North","Komponen diukur dari Utara","For distance d on bearing β, east = d sin β and north = d cos β because β starts at the north axis. Signs encode direction: east positive, west negative; north positive, south negative. Combine component changes, then use Pythagoras or a triangle rule for the resultant.","Untuk jarak d pada bearing β, komponen timur = d sin β dan utara = d cos β karena β dimulai dari sumbu utara. Tanda menunjukkan arah: timur positif, barat negatif; utara positif, selatan negatif. Jumlahkan perubahan komponen, lalu gunakan Pythagoras atau aturan segitiga untuk resultannya."],["Sanity checks","Pemeriksaan kewajaran","A due-east bearing gives zero north component; due north gives zero east component. A reverse bearing differs by 180°. Check these before using a sine/cosine rule, and keep the original route direction distinct from a back bearing.","Bearing tepat ke timur memberi komponen utara nol; tepat ke utara memberi komponen timur nol. Back bearing berbeda 180°. Periksa hal ini sebelum memakai aturan sinus/cosinus, dan bedakan arah rute awal dari back bearing."]])+`<section class="scene compass-wrap"><div class="visual-panel" id="bearingExplorer">${compassSvg(beta,18)}<div class="control-row"><label>${L('Bearing β','Bearing β')}</label><input type="range" min="0" max="359" value="${beta}" step="1" data-bearing-range><span class="metric" data-bearing-value>${String(beta).padStart(3,'0')}°</span></div></div><div class="concept-copy"><div class="scene-label">${L('NORTH FIRST','UTARA DULU')}</div><div class="big-question">${L('Why is East the sine component?','Mengapa komponen Timur memakai sinus?')}</div><p>${L('The bearing angle is measured from North. Relative to that angle, east is opposite and north is adjacent.','Sudut bearing diukur dari Utara. Terhadap sudut itu, komponen timur berada di depan dan komponen utara bersebelahan.')}</p><div class="formula-flow"><div class="formula">E = d sin β &nbsp;&nbsp; N = d cos β</div></div><div class="component-readout"><div class="component-card">${L('East','Timur')}<strong data-east>${fmt(E,1)}</strong></div><div class="component-card">${L('North','Utara')}<strong data-north>${fmt(N,1)}</strong></div></div></div></section><section class="scene">${guided('Two-leg journey','Perjalanan dua tahap','A boat travels 12 km from A to B on bearing 060°, then 9 km from B to C on bearing 150°. Find ∠ABC and AC.','Sebuah kapal bergerak 12 km dari A ke B pada bearing 060°, lalu 9 km dari B ke C pada bearing 150°. Tentukan ∠ABC dan AC.','challenge',['Reverse bearing of A from B is 240°.','Therefore ∠ABC = 240° − 150° = 90°.','The triangle is now right-angled: AC = √(12²+9²) = 15 km.'],['Bearing balik A dari B adalah 240°.','Jadi ∠ABC = 240° − 150° = 90°.','Segitiganya sekarang siku-siku: AC = √(12²+9²) = 15 km.'])}</section>${practiceHTML('H')}${completePanel('H')}`}
function unitI(){const s=sections[8];return sectionHeader(s,'Elevation and depression angles are measured from horizontal reference lines, not from vertical walls or towers.','Sudut elevasi dan depresi diukur dari garis horizontal, bukan dari dinding atau menara vertikal.')+academicBridge('From a direction to a right triangle','Dari arah menuju segitiga siku-siku',[['Line of sight and observer horizontal','Garis pandang dan horizontal pengamat','The line of sight joins the observer to the object. The observer horizontal is a line through the observer parallel to level ground. The vertical height difference is perpendicular to both horizontal lines; these three segments form the relevant right triangle.','Garis pandang menghubungkan pengamat dengan objek. Horizontal pengamat adalah garis melalui pengamat yang sejajar tanah datar. Selisih tinggi vertikal tegak lurus terhadap kedua garis horizontal; ketiga ruas ini membentuk segitiga siku-siku yang relevan.'],['Elevation and depression','Elevasi dan depresi','Elevation is measured upward from the observer horizontal to the sight line; depression is measured downward from that horizontal. Neither is measured from the vertical wall or tower.','Elevasi diukur ke atas dari horizontal pengamat menuju garis pandang; depresi diukur ke bawah dari horizontal itu. Keduanya tidak diukur dari dinding atau menara yang vertikal.'],['Why the angle transfers','Mengapa sudutnya berpindah','The observer horizontal and ground horizontal are parallel. The sight line is a transversal, so the acute depression angle equals the alternate/corresponding elevation angle at the ground point. This places the angle inside the right triangle.','Horizontal pengamat dan tanah sejajar. Garis pandang menjadi garis potong, sehingga sudut depresi lancip sama dengan sudut elevasi berseberangan/sehadap di titik tanah. Dengan demikian sudut tersebut dapat ditempatkan di dalam segitiga siku-siku.'],['Choose the ratio from the target','Pilih rasio berdasarkan target','After justifying the right triangle, identify the target: vertical difference, horizontal distance, or sight-line length. Relative to the marked angle, use tangent for opposite/adjacent, sine for opposite/hypotenuse, or cosine for adjacent/hypotenuse.','Setelah memastikan segitiga siku-siku, kenali target: selisih vertikal, jarak horizontal, atau panjang garis pandang. Relatif terhadap sudut yang ditandai, gunakan tangen untuk depan/samping, sinus untuk depan/miring, atau cosinus untuk samping/miring.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('HORIZONTAL REFERENCE','ACUAN HORIZONTAL')}</div><div class="big-question">${L('Which line is the angle measured from?','Sudutnya diukur dari garis yang mana?')}</div><p>${L('Horizontal lines at different heights are parallel. This lets an angle of depression at the observer match the corresponding angle of elevation at the ground point.','Garis horizontal pada ketinggian berbeda saling sejajar. Karena itu sudut depresi di pengamat sama dengan sudut elevasi yang bersesuaian di titik tanah.')}</p>${mascot('sheet2_bottom_02.png',L('Mark the horizontal first. That prevents the most common orientation error.','Tandai garis horizontal terlebih dahulu. Ini mencegah kesalahan orientasi yang paling umum.'))}</div><div class="visual-panel">${elevationSvg()}<div class="visual-caption">${L('The line of sight and the horizontal reference reveal the relevant right triangle.','Garis pandang dan acuan horizontal memperlihatkan segitiga siku-siku yang relevan.')}</div></div></section><section class="scene">${guided('Angle of depression','Sudut depresi','A cliff is 50 m high. From the top, the angle of depression to a boat is 28°. Find the horizontal distance to the foot of the cliff.','Sebuah tebing tingginya 50 m. Dari puncak, sudut depresi ke kapal adalah 28°. Tentukan jarak horizontal kapal ke kaki tebing.','core',['Draw the horizontal through the top of the cliff.','The angle of elevation at the boat is also 28° because the horizontals are parallel.','tan28° = 50/x, so x ≈ 94.0 m.'],['Gambar garis horizontal melalui puncak tebing.','Sudut elevasi di kapal juga 28° karena garis-garis horizontal sejajar.','tan28° = 50/x, sehingga x ≈ 94,0 m.'])}</section>${practiceHTML('I')}${completePanel('I')}`}
function unitJ(){const s=sections[9];return sectionHeader(s,'The final triangle may not initially contain enough information. Solve a nearby triangle for a gateway side or angle and transfer it.','Segitiga akhir mungkin belum memiliki cukup informasi. Selesaikan segitiga di dekatnya untuk mendapatkan sisi atau sudut penghubung, lalu pindahkan informasi itu.')+academicBridge('Build the dependency chain','Bangun rantai ketergantungan',[['Start from the target triangle','Mulai dari segitiga target','Name the requested quantity and the triangle containing it. List the facts that triangle needs for a valid method—for example, SAS for a cosine-rule side or a complete opposite pair for sine rule.','Sebutkan besaran yang diminta dan segitiga yang memuatnya. Daftarkan fakta yang dibutuhkan untuk metode yang sah—misalnya SAS untuk sisi dengan aturan cosinus atau pasangan berhadapan lengkap untuk aturan sinus.'],['Define a gateway quantity','Definisikan besaran penghubung','A gateway quantity is a missing side or angle found in a different, solvable triangle and then transferred to the target triangle. A shared diagonal has the same length in both triangles.','Besaran penghubung adalah sisi atau sudut yang belum diketahui, ditemukan pada segitiga lain yang dapat diselesaikan, lalu dipindahkan ke segitiga target. Diagonal bersama memiliki panjang sama pada kedua segitiga.'],['Why direct calculation fails','Mengapa hitung langsung gagal','A formula cannot create independent information that is absent from the target triangle. The neighbouring triangle supplies that missing fact. The useful order is therefore target need ← supplier triangle ← solve supplier ← transfer ← solve target.','Rumus tidak dapat menciptakan informasi bebas yang tidak ada pada segitiga target. Segitiga tetangga menyediakan fakta yang hilang. Urutan yang berguna ialah kebutuhan target ← segitiga pemasok ← selesaikan pemasok ← pindahkan informasi ← selesaikan target.'],['Reassess after transfer','Nilai kembali setelah informasi dipindahkan','Once the gateway is known, classify the target triangle again. It may now be SAS, SSS, or contain an opposite pair; the appropriate method can change only after this transfer.','Setelah penghubung diketahui, klasifikasikan ulang segitiga target. Kini mungkin menjadi SAS, SSS, atau memiliki pasangan berhadapan; metode baru dapat dipilih setelah informasi dipindahkan.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('GATEWAY QUANTITY','BESARAN PENGHUBUNG')}</div><div class="big-question">${L('What must be found before the target triangle becomes solvable?','Apa yang harus dicari agar segitiga target menjadi dapat diselesaikan?')}</div><p>${L('A diagonal often acts as a bridge between two triangles. Do not try to solve the second triangle before the shared diagonal or angle is available.','Diagonal sering menjadi jembatan antara dua segitiga. Jangan mencoba menyelesaikan segitiga kedua sebelum diagonal atau sudut bersama tersedia.')}</p><div class="dependency-board"><div class="dep-card"><strong>1</strong>${L('Find a solvable triangle','Cari segitiga yang dapat diselesaikan')}</div><div class="dep-card"><strong>2</strong>${L('Compute the gateway quantity','Hitung besaran penghubung')}</div><div class="dep-card"><strong>3</strong>${L('Transfer it to the target triangle','Pindahkan ke segitiga target')}</div><div class="dep-card"><strong>4</strong>${L('Finish and verify','Selesaikan dan verifikasi')}</div></div>${mascot('sheet1_bottom_04.png',L('If the target triangle is stuck, look next door. One nearby triangle may already have enough information.','Jika segitiga target buntu, lihat segitiga di sebelahnya. Mungkin salah satunya sudah memiliki cukup informasi.'))}</div><div class="visual-panel"><div class="gateway-controls" id="gatewayControls">${[1,2,3].map(step=>`<button class="gateway-step ${step===state.gatewayStep?'active':''}" data-gateway-step="${step}" aria-pressed="${step===state.gatewayStep}">${L('STEP '+step,'LANGKAH '+step)}</button>`).join('')}</div><div id="gatewayDiagram">${gatewaySvg(state.gatewayStep)}</div><div class="diagram-note" id="gatewayNote">${gatewayStepText(state.gatewayStep)}</div></div></section><section class="scene">${guided('Hidden diagonal','Diagonal tersembunyi','Diagonal AC divides quadrilateral ABCD. In △ABC, AB=8, BC=11, ∠ABC=60°. Also AD=10 and ∠CAD=35°. Find CD.','Diagonal AC membagi segiempat ABCD. Pada △ABC, AB=8, BC=11, ∠ABC=60°. Selain itu AD=10 dan ∠CAD=35°. Tentukan CD.','challenge',['Triangle ABC is solvable first because it has SAS data.','AC² = 8² + 11² − 2(8)(11)cos60° = 97, so AC=√97.','Now triangle ACD has AC, AD and included angle 35°.','Use cosine rule again to get CD ≈ 5.97.'],['Segitiga ABC diselesaikan dulu karena memiliki data SAS.','AC² = 8² + 11² − 2(8)(11)cos60° = 97, sehingga AC=√97.','Sekarang segitiga ACD memiliki AC, AD, dan sudut apit 35°.','Gunakan aturan cosinus lagi untuk memperoleh CD ≈ 5,97.'])}</section>${practiceHTML('J')}${completePanel('J')}`}
function unitK(){const s=sections[10];return sectionHeader(s,'Reverse problems start from an outcome. Let the geometry produce equations instead of calculating every trigonometric value numerically.','Soal balik dimulai dari hasil. Biarkan geometri membentuk persamaan, bukan menghitung setiap nilai trigonometri secara numerik.')+academicBridge('Reverse the direction of the reasoning','Balik arah penalaran',[['Forward versus reverse','Arah maju dan arah balik','Forward: givens → relationship → calculated result. Reverse: known result or condition → express it using geometry → form an equation → recover an unknown. The same area, sine, or cosine relationship may be used in either direction.','Arah maju: data → hubungan → hasil hitung. Arah balik: hasil atau syarat diketahui → nyatakan dengan geometri → bentuk persamaan → cari besaran yang belum diketahui. Hubungan luas, sinus, atau cosinus yang sama dapat dipakai ke dua arah.'],['Cancel a shared factor structurally','Coret faktor bersama berdasarkan struktur','If two equal areas use the same included angle θ, then ½uv sinθ = ½wx sinθ. For a non-degenerate triangle, 0°<θ<180°, so ½sinθ is non-zero and can be cancelled, leaving uv=wx. There is no need to evaluate sinθ.','Jika dua luas sama menggunakan sudut apit θ yang sama, maka ½uv sinθ = ½wx sinθ. Untuk segitiga tak-degenerat, 0°<θ<180°, sehingga ½sinθ tidak nol dan dapat dicoret; tersisa uv=wx. Nilai sinθ tidak perlu dihitung.'],['When cancellation is not allowed','Kapan faktor tidak dapat dicoret','The factors must be identical and non-zero. Different angles give different sine factors; a degenerate zero angle would not describe a triangle. Cancellation is justified by the geometry, not a visual shortcut.','Faktornya harus benar-benar sama dan tidak nol. Sudut berbeda memberi faktor sinus berbeda; sudut nol yang degenerat bukan segitiga. Pencoretan dibenarkan oleh geometri, bukan jalan pintas visual.'],['Validate the recovered value','Validasi nilai yang ditemukan','An equation may have multiple roots. Check positive lengths, the angle domain, triangle inequality, and the original condition. A root becomes an answer only after it describes a possible configuration.','Persamaan mungkin memiliki beberapa akar. Periksa panjang positif, domain sudut, ketaksamaan segitiga, dan syarat awal. Akar baru menjadi jawaban setelah menggambarkan konfigurasi yang mungkin.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('REVERSE REASONING','PENALARAN BALIK')}</div><div class="big-question">${L('Can a trigonometric factor cancel before you ever evaluate it?','Bisakah faktor trigonometri saling menghilangkan sebelum nilainya dihitung?')}</div><p>${L('When two triangles share the same included angle and have equal areas, the common sine factor may cancel. The geometry creates the equation; numerical trigonometry may be unnecessary.','Ketika dua segitiga memiliki sudut apit yang sama dan luas yang sama, faktor sinus yang sama dapat saling menghilangkan. Geometri membentuk persamaannya; perhitungan trigonometri numerik mungkin tidak diperlukan.')}</p><div class="formula-flow"><div class="formula">½(8)(12)sin40° = ½(6)(x)sin40°</div><div class="formula">x = 16</div></div></div><div class="visual-panel">${reversePairSvg()}<div class="visual-caption">${L('Same included angle + equal area creates a direct relation between side products.','Sudut apit sama + luas sama menghasilkan hubungan langsung antara hasil kali sisi.')}</div></div></section>${completePanel('K')}`}
function unitL(){const s=sections[11];return sectionHeader(s,'Algebra may produce several candidate values. Geometry must still check positive lengths, triangle inequality, angle range and original conditions.','Aljabar dapat menghasilkan beberapa kandidat. Geometri tetap harus mengecek panjang positif, ketaksamaan segitiga, rentang sudut, dan syarat awal.')+academicBridge('From an equation to a possible triangle','Dari persamaan menuju segitiga yang mungkin',[['Translate the geometry','Terjemahkan geometri','Match the formula to the actual triangle and place parentheses around side expressions. For cosine rule, the side opposite the included angle must be the isolated target side.','Cocokkan rumus dengan segitiga sebenarnya dan beri tanda kurung pada ekspresi sisi. Untuk aturan cosinus, sisi yang berhadapan dengan sudut apit harus menjadi sisi target yang diisolasi.'],['Keep algebraic roots as candidates','Anggap akar aljabar sebagai kandidat','Solve the resulting equation and record every root before deciding. Algebra checks only whether a value satisfies the equation; it does not know that a parameter represents lengths or angles.','Selesaikan persamaan dan catat semua akar sebelum memutuskan. Aljabar hanya memeriksa apakah nilai memenuhi persamaan; aljabar tidak mengetahui bahwa parameter mewakili panjang atau sudut.'],['Apply the geometric domain','Terapkan domain geometri','Require every side length to be positive, each interior angle to lie between 0° and 180°, and three sides to satisfy the triangle inequality. Then substitute candidates into the original condition.','Pastikan setiap panjang sisi positif, tiap sudut dalam berada antara 0° dan 180°, dan tiga sisi memenuhi ketaksamaan segitiga. Lalu uji kandidat pada syarat awal.'],['Why a root can be impossible','Mengapa akar bisa mustahil','A root can satisfy a cosine-rule equation while making x+1 negative, or producing three lengths that cannot close into a triangle. The equation encodes one relation, not every domain restriction of the geometry.','Akar dapat memenuhi persamaan aturan cosinus tetapi membuat x+1 negatif atau menghasilkan tiga panjang yang tidak dapat membentuk segitiga. Persamaan hanya mengodekan satu hubungan, bukan semua batas domain geometri.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('CANDIDATE ≠ VALID','KANDIDAT ≠ VALID')}</div><div class="big-question">${L('What does the algebra know — and what does it not know?','Apa yang diketahui aljabar — dan apa yang tidak diketahuinya?')}</div><p>${L('A quadratic formula only solves the equation you gave it. It does not know that a side length cannot be negative or that a triangle must satisfy its geometric constraints.','Rumus kuadrat hanya menyelesaikan persamaan yang diberikan. Ia tidak tahu bahwa panjang sisi tidak boleh negatif atau bahwa segitiga harus memenuhi syarat geometrinya.')}</p><div class="validity-list"><div class="validity-item">✓ ${L('Positive lengths','Panjang positif')}</div><div class="validity-item">✓ ${L('Triangle inequality','Ketaksamaan segitiga')}</div><div class="validity-item">✓ ${L('Angle ranges','Rentang sudut')}</div><div class="validity-item">✓ ${L('Original condition','Syarat awal')}</div></div>${mascot('sheet2_top_05.png',L('The calculator returns algebraic candidates. You return the geometrically valid answer.','Kalkulator mengembalikan kandidat aljabar. Kamu yang menentukan jawaban geometri yang valid.'))}</div><div class="visual-panel">${parameterTriangleSvg()}<div class="diagram-note">${L('The diagram shows the given expressions only; no solved side values are exposed.','Diagram hanya menampilkan ekspresi yang diberikan; nilai sisi hasil penyelesaian tidak ditampilkan.')}</div></div></section><section class="scene">${guided('Parameter from cosine rule','Parameter dari aturan cosinus','AB=x+1, AC=x+3, ∠A=60°, BC=7. Find x and reject invalid candidates.','AB=x+1, AC=x+3, ∠A=60°, BC=7. Tentukan x dan tolak kandidat yang tidak valid.','advanced',['Cosine rule gives 49=(x+1)²+(x+3)²−(x+1)(x+3).','This simplifies to x²+4x−42=0.','x = −2 ± √46.','The negative branch makes side lengths invalid, so x = −2 + √46 ≈ 4.78.'],['Aturan cosinus memberi 49=(x+1)²+(x+3)²−(x+1)(x+3).','Ini menyederhana menjadi x²+4x−42=0.','x = −2 ± √46.','Cabang negatif membuat panjang sisi tidak valid, sehingga x = −2 + √46 ≈ 4,78.'])}</section>${practiceHTML('L')}${completePanel('L')}`}
function feasibleNote(g,b){if(g.count===0)return L('The circle misses the ray: a<h.','Lingkaran tidak mencapai sinar: a<h.');if(Math.abs(b-6)<1e-8)return L('A lies on the circle too, but that intersection is degenerate (zero side); one proper triangle remains.','Titik A juga berada pada lingkaran, tetapi perpotongan itu degenerat (sisi nol); tersisa satu segitiga yang valid.');if(g.tangent)return L('The circle is tangent to the ray: one right-triangle configuration.','Lingkaran menyinggung sinar: satu konfigurasi segitiga siku-siku.');if(g.count===2)return L('The circle crosses the ray twice: two distinct triangle configurations.','Lingkaran memotong sinar di dua titik: dua konfigurasi segitiga berbeda.');return L('Only one forward intersection is valid; the other root is at or behind A.','Hanya satu perpotongan ke depan yang valid; akar lainnya berada di A atau di belakangnya.')}
function unitM(){const s=sections[12];const b=Number(state.feasibleB)||8,g=feasibleGeom(b),count=g.count;return sectionHeader(s,'For SSA data, choose the intended 0/1/2-solution state from geometry, not from random arithmetic.','Untuk data SSA, tentukan keadaan 0/1/2 solusi dari geometri, bukan dari aritmetika acak.')+academicBridge('Explain the height before counting triangles','Pahami tinggi sebelum menghitung segitiga',[['The construction','Konstruksinya','For acute A, let b run along a fixed ray from A and let a be the fixed length opposite A. The endpoint must lie on both the ray and a circle of radius a centred at the end of b.','Untuk A lancip, sisi b terletak pada sinar tetap dari A dan a adalah panjang tetap yang berhadapan dengan A. Ujung sisi harus berada pada sinar sekaligus lingkaran berjari-jari a berpusat di ujung b.'],['Meaning of h=b sin A','Makna h=b sin A','Drop a perpendicular from the circle centre to the ray. In the right triangle, b is the hypotenuse and h is opposite A, so sin A=h/b and h=b sin A. Thus h is the shortest distance from the centre to the ray—not an assumed diagram length.','Tarik garis tegak lurus dari pusat lingkaran ke sinar. Dalam segitiga siku-siku, b adalah hipotenusa dan h berhadapan dengan A, sehingga sin A=h/b dan h=b sin A. Jadi h adalah jarak terpendek pusat ke sinar—bukan panjang yang diasumsikan dari gambar.'],['Zero, one, or two intersections','Nol, satu, atau dua perpotongan','For the acute-angle case with a<b: a<h gives zero; a=h gives one tangent configuration, a right triangle; h<a<b gives two intersections and two triangles. If a≥b, only one intersection lies on the forward ray.','Untuk kasus sudut lancip dengan a<b: a<h memberi nol; a=h memberi satu konfigurasi singgung berupa segitiga siku-siku; h<a<b memberi dua perpotongan dan dua segitiga. Jika a≥b, hanya satu perpotongan berada pada sinar ke depan.'],['Connect to Unit D','Hubungkan ke Unit D','The two intersections correspond to supplementary angles θ and 180°−θ with the same sine. At tangency, the two configurations meet at the perpendicular point; this is the one-solution boundary.','Dua perpotongan berkorespondensi dengan sudut suplementer θ dan 180°−θ yang sinusnya sama. Saat menyinggung, kedua konfigurasi bertemu di titik tegak lurus; inilah batas dengan satu solusi.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('FEASIBILITY','KEMUNGKINAN')}</div><div class="big-question">${L('How many triangles can this fixed side actually reach?','Berapa banyak segitiga yang dapat dicapai oleh sisi tetap ini?')}</div><p>${L('With A=40° and a=6 while side b varies, the critical perpendicular height is h=b sin40°. Two triangles occur when h<a<b.','Dengan A=40° dan a=6 sementara sisi b berubah, tinggi tegak lurus kritis adalah h=b sin40°. Dua segitiga terjadi ketika h<a<b.')}</p><div class="formula-flow"><div class="formula">b sin40° &lt; 6 &lt; b</div><div class="reason-note">${L('This gives 6 < b < 6/sin40° ≈ 9.33 for two triangles.','Ini memberi 6 < b < 6/sin40° ≈ 9,33 untuk dua segitiga.')}</div></div></div><div class="visual-panel" id="feasibleExplorer">${feasibilitySvg(b)}<div class="control-row"><label>b</label><input type="range" min="4" max="11" step="any" value="${b}" data-feasible-range aria-label="${L('Side b','Sisi b')}"><span class="metric" data-feasible-value>${fmt(b,1)}</span><button type="button" data-tangent-boundary>${L('Show tangency boundary','Tampilkan batas singgung')}</button></div><div class="status-row" aria-live="polite"><span data-feasible-count="0" class="status-pill ${count===0?'active':''}">0</span><span data-feasible-count="1" class="status-pill ${count===1?'active':''}">1</span><span data-feasible-count="2" class="status-pill ${count===2?'active':''}">2</span><span data-feasible-status>${count===0?L('0 configurations','0 konfigurasi'):count===1?L('1 configuration','1 konfigurasi'):L('2 configurations','2 konfigurasi')}</span></div><div class="diagram-note" data-feasible-note>${feasibleNote(g,b)}</div></div></section>${completePanel('M')}`}
function unitN(){const s=sections[13];return sectionHeader(s,'Older topics remain active tools. Compare two legitimate routes and choose the one that makes the structure clearest.','Topik lama tetap menjadi alat aktif. Bandingkan dua jalur yang sama-sama sah dan pilih yang paling jelas memperlihatkan struktur.')+academicBridge('Compare two routes through the same circle geometry','Bandingkan dua jalur pada geometri lingkaran yang sama',[['Route 1 — whole isosceles triangle','Jalur 1 — segitiga sama kaki utuh','OA=OB=r and the included central angle is θ. Cosine rule gives AB²=2r²−2r²cosθ, hence AB=r√(2−2cosθ). This is direct: one triangle and one rule.','OA=OB=r dan sudut pusat apitnya θ. Aturan cosinus memberi AB²=2r²−2r²cosθ, sehingga AB=r√(2−2cosθ). Ini langsung: satu segitiga dan satu aturan.'],['Route 2 — symmetry and a right triangle','Jalur 2 — simetri dan segitiga siku-siku','The perpendicular from O to AB bisects the chord and angle θ. In one half, hypotenuse r, opposite AB/2, and angle θ/2 give sin(θ/2)=AB/(2r), so AB=2r sin(θ/2).','Garis tegak lurus dari O ke AB membagi dua tali busur dan sudut θ. Pada setengah segitiga, hipotenusa r, sisi depan AB/2, dan sudut θ/2 memberi sin(θ/2)=AB/(2r), sehingga AB=2r sin(θ/2).'],['Compare and choose','Bandingkan dan pilih','The cosine route has fewer construction steps and uses the given central angle directly. The bisection route reveals symmetry and gives a right triangle, useful when half-angle or perpendicular structure matters later. Both routes must agree because they describe the same chord.','Jalur cosinus memiliki lebih sedikit langkah konstruksi dan langsung memakai sudut pusat yang diketahui. Jalur pembagian dua memperlihatkan simetri dan menghasilkan segitiga siku-siku, berguna jika setengah sudut atau struktur tegak lurus dibutuhkan kemudian. Kedua jalur harus cocok karena menggambarkan tali busur yang sama.']])+`<section class="scene focus-grid"><div class="concept-copy"><div class="scene-label">${L('COMPARE ROUTES','BANDINGKAN JALUR')}</div><div class="big-question">${L('Should you solve the original non-right triangle, or create a right triangle first?','Haruskah kamu menyelesaikan segitiga non-siku-siku asli, atau membuat segitiga siku-siku terlebih dahulu?')}</div><p>${L('A chord AB in a circle of radius r subtends central angle θ. Both routes are mathematically valid; the strategic lesson is to recognize what each representation makes easier.','Tali busur AB pada lingkaran berjari-jari r membentuk sudut pusat θ. Kedua jalur sah secara matematis; pelajaran strategisnya adalah mengenali apa yang dibuat lebih mudah oleh setiap representasi.')}</p><div class="route-tabs"><button class="${state.route==='cos'?'active':''}" data-route="cos" aria-pressed="${state.route==='cos'}">${L('Route 1: cosine rule','Jalur 1: aturan cosinus')}</button><button class="${state.route==='bisect'?'active':''}" data-route="bisect" aria-pressed="${state.route==='bisect'}">${L('Route 2: bisect','Jalur 2: bagi dua')}</button></div><div class="route-panel ${state.route==='cos'?'show':''}" data-route-panel="cos"><div class="formula-flow"><div class="formula">AB = r√(2−2cosθ)</div></div><p>${L('Work directly in the original isosceles triangle.','Bekerja langsung pada segitiga sama kaki asli.')}</p></div><div class="route-panel ${state.route==='bisect'?'show':''}" data-route-panel="bisect"><div class="formula-flow"><div class="formula">AB = 2r sin(θ/2)</div></div><p>${L('Use symmetry to create a right triangle with half the chord.','Gunakan simetri untuk membentuk segitiga siku-siku dengan setengah tali busur.')}</p></div></div><div class="visual-panel"><div id="chordDiagram">${chordSvg(state.route)}</div><div class="visual-caption">${L('No numerical chord value or derived angle is shown before the reasoning requires it.','Tidak ada nilai tali busur numerik atau sudut turunan yang ditampilkan sebelum diperlukan dalam penalaran.')}</div></div></section>${practiceHTML('N')}${completePanel('N')}`}
function unitO(){const s=sections[14];return sectionHeader(s,'Advanced difficulty comes from hidden method, multi-stage dependencies, reconstruction, parameters, constraints and mixed topics — not from ugly arithmetic.','Kesulitan lanjutan berasal dari metode tersembunyi, ketergantungan bertahap, rekonstruksi, parameter, syarat, dan campuran topik — bukan dari aritmetika yang dibuat jelek.')+academicBridge('Advanced means a less obvious chain, not harder arithmetic','Lanjutan berarti rantai penalaran kurang terlihat, bukan hitungan lebih sulit',[['Hidden method — split the shape','Metode tersembunyi — bagi bentuknya','Mini-case: a diagonal divides a quadrilateral into two triangles. The target side lies in the second triangle, but the first triangle has SAS data. Find the diagonal by cosine rule, transfer it, then solve the target triangle.','Contoh mini: diagonal membagi segiempat menjadi dua segitiga. Sisi target berada pada segitiga kedua, tetapi segitiga pertama memiliki data SAS. Cari diagonal dengan aturan cosinus, pindahkan, lalu selesaikan segitiga target.'],['Parameter — recover a length','Parameter — cari panjang dari syarat','Mini-case: sides x+2 and x+5 meet at known angle, with fixed opposite side. Cosine rule creates an equation in x. Keep all roots until positive lengths and triangle inequality identify the valid one.','Contoh mini: sisi x+2 dan x+5 bertemu pada sudut diketahui, dengan sisi di depannya tetap. Aturan cosinus membentuk persamaan x. Simpan semua akar sampai panjang positif dan ketaksamaan segitiga menentukan yang valid.'],['Constraint — determine a range','Syarat — tentukan rentang','Mini-case: in acute SSA, compare fixed a with h=b sin A and b. The inequalities determine whether the circle misses the ray, touches once, or intersects twice; the result is a range, not one calculated angle.','Contoh mini: pada SSA lancip, bandingkan a tetap dengan h=b sin A dan b. Ketaksamaan menentukan apakah lingkaran tidak mencapai sinar, menyinggung sekali, atau memotong dua kali; hasilnya rentang, bukan satu sudut hitung.'],['Gateway — transfer one fact','Penghubung — pindahkan satu fakta','Mini-case: the target triangle needs an opposite pair but the side is in a neighbouring triangle. Solve the neighbour, transfer the shared side, and reassess the available rule.','Contoh mini: segitiga target membutuhkan pasangan berhadapan tetapi sisinya berada pada segitiga tetangga. Selesaikan segitiga tetangga, pindahkan sisi bersama, lalu nilai kembali aturan yang tersedia.'],['Synthesis — compare representations','Sintesis — bandingkan representasi','A chord can be found by cosine rule in the whole isosceles triangle or by bisection and right-triangle trigonometry. Advanced work means choosing and defending the route that supports the whole solution.','Tali busur dapat dicari dengan aturan cosinus pada segitiga sama kaki utuh atau dengan membaginya dan memakai trigonometri siku-siku. Soal lanjutan berarti memilih serta menjelaskan jalur yang mendukung penyelesaian secara utuh.']])+`<section class="scene"><div class="scene-label">${L('ADVANCED STRUCTURES','STRUKTUR LANJUTAN')}</div><div class="toolkit"><div class="tool-row"><strong>${L('Hidden method','Metode tersembunyi')}</strong><p>${L('The question does not name the rule.','Soal tidak menyebut aturan yang harus dipakai.')}</p></div><div class="tool-row"><strong>${L('Gateway quantity','Besaran penghubung')}</strong><p>${L('Triangle 2 depends on a side or angle found in triangle 1.','Segitiga 2 bergantung pada sisi atau sudut yang ditemukan dari segitiga 1.')}</p></div><div class="tool-row"><strong>${L('Reconstruction','Rekonstruksi')}</strong><p>${L('The outcome is known and earlier geometry must be recovered.','Hasil diketahui dan geometri sebelumnya harus dibangun kembali.')}</p></div><div class="tool-row"><strong>${L('Parameter','Parameter')}</strong><p>${L('A geometric condition creates an equation in x, k or θ.','Syarat geometri membentuk persamaan dalam x, k, atau θ.')}</p></div><div class="tool-row"><strong>${L('Constraint','Syarat')}</strong><p>${L('Determine whether 0, 1 or 2 configurations are possible.','Tentukan apakah ada 0, 1, atau 2 konfigurasi yang mungkin.')}</p></div><div class="tool-row"><strong>${L('Synthesis','Sintesis')}</strong><p>${L('Combine triangle trigonometry with circles, radians, bearings or algebra.','Gabungkan trigonometri segitiga dengan lingkaran, radian, bearing, atau aljabar.')}</p></div></div>${mascot('sheet1_bottom_04.png',L('There may be more than one route. Prefer the one that creates the cleanest chain of justified quantities.','Mungkin ada lebih dari satu jalur. Pilih jalur yang menghasilkan urutan besaran terjustifikasi paling bersih.'))}</section>${practiceHTML('O')}${completePanel('O')}`}
function synthesis(){const s=sections[15];return sectionHeader(s,'Finish by making method choice explicit. The central skill is not remembering more formulas; it is recognizing structure and verifying geometry.','Akhiri topik dengan membuat pemilihan metode menjadi eksplisit. Keterampilan utamanya bukan menghafal lebih banyak rumus, melainkan mengenali struktur dan memverifikasi geometri.')+academicBridge('A flexible nine-question reasoning pathway','Jalur penalaran fleksibel dengan sembilan pertanyaan',[['1 · Identify the target','1 · Tentukan target','What exact length, angle, area, or condition is requested? Mark it before calculating.','Panjang, sudut, luas, atau syarat apa tepatnya yang diminta? Tandai sebelum menghitung.'],['2 · Locate its triangle or shape','2 · Temukan segitiga atau bentuknya','Find the smallest relevant shape containing the target; interpret the context and reference lines first.','Temukan bentuk relevan terkecil yang memuat target; tafsirkan konteks dan garis acuannya terlebih dahulu.'],['3 · Mark genuine givens','3 · Tandai data yang benar-benar diketahui','Separate stated facts from appearance. A right angle, parallel pair, or equal length needs justification.','Pisahkan fakta yang dinyatakan dari tampilan gambar. Sudut siku-siku, pasangan sejajar, atau panjang sama harus memiliki alasan.'],['4 · Test simpler geometry','4 · Uji geometri sederhana','Try angle sum, parallel-line angles, Pythagoras, similarity, symmetry, or right-triangle ratios when justified.','Coba jumlah sudut, sudut pada garis sejajar, Pythagoras, kesebangunan, simetri, atau rasio segitiga siku-siku jika beralasan.'],['5 · Read the information structure','5 · Baca struktur informasinya','Pair sides with opposite angles and classify what is available: opposite pair, SAS, SSS, or another structure.','Pasangkan sisi dengan sudut di depannya dan klasifikasikan data: pasangan berhadapan, SAS, SSS, atau struktur lain.'],['6 · Find any gateway quantity','6 · Cari besaran penghubung','If something is missing, ask what the target triangle needs and which neighbouring triangle can supply it.','Jika ada yang kurang, tanyakan kebutuhan segitiga target dan segitiga tetangga yang dapat menyediakannya.'],['7 · Select a method now available','7 · Pilih metode yang kini tersedia','Use sine rule with an opposite pair, cosine rule for SAS side or SSS angle, and area formula for two sides with included angle. Treat SSA candidates carefully.','Gunakan aturan sinus dengan pasangan berhadapan, aturan cosinus untuk sisi SAS atau sudut SSS, dan rumus luas untuk dua sisi dengan sudut apit. Tangani kandidat SSA dengan cermat.'],['8 · Solve with precision','8 · Selesaikan dengan teliti','Substitute correctly, solve algebraically, retain precision in intermediate values, and include units.','Substitusikan dengan benar, selesaikan aljabar, jaga ketelitian nilai antara, dan sertakan satuan.'],['9 · Validate the geometry','9 · Validasi geometri','Check positive lengths, angle domain and sum, triangle inequality, plausible size, SSA configuration count, and the original condition.','Periksa panjang positif, domain dan jumlah sudut, ketaksamaan segitiga, ukuran yang wajar, jumlah konfigurasi SSA, dan syarat awal.']])+`<section class="scene"><div class="scene-label">${L('CONCISE DECISION SUMMARY','RINGKASAN KEPUTUSAN')}</div><div class="toolkit"><div class="tool-row"><strong>${L('Right triangle','Segitiga siku-siku')}</strong><br>${L('Pythagoras or sin, cos, tan','Pythagoras atau sin, cos, tan')}</div><div class="tool-row"><strong>${L('Opposite side-angle pair','Pasangan sisi-sudut berhadapan')}</strong><br>${L('Sine rule','Aturan sinus')}</div><div class="tool-row"><strong>${L('Two sides + included angle','Dua sisi + sudut apit')}</strong><br>${L('Cosine rule for side; ½ab sinC for area','Aturan cosinus untuk sisi; ½ab sinC untuk luas')}</div><div class="tool-row"><strong>${L('Three sides','Tiga sisi')}</strong><br>${L('Cosine rule for angle','Aturan cosinus untuk sudut')}</div><div class="tool-row"><strong>SSA</strong><br>${L('Sine rule + supplementary-angle validity check','Aturan sinus + cek keabsahan sudut suplementer')}</div><div class="tool-row"><strong>${L('Bearings','Bearing')}</strong><br>${L('Draw North; convert to triangle or components','Gambar Utara; ubah menjadi segitiga atau komponen')}</div><div class="tool-row"><strong>${L('Elevation/depression','Elevasi/depresi')}</strong><br>${L('Mark horizontal and line of sight','Tandai horizontal dan garis pandang')}</div><div class="tool-row"><strong>${L('Multi-triangle','Beberapa segitiga')}</strong><br>${L('Find the gateway quantity first','Cari besaran penghubung terlebih dahulu')}</div></div></section><section class="scene"><div class="scene-label">${L('COMMON ERRORS','KESALAHAN UMUM')}</div><div class="misconception-grid">${[
['Mismatching sides and opposite angles','Salah memasangkan sisi dan sudut di depannya'],['Wrong included angle in cosine rule','Salah memilih sudut apit pada aturan cosinus'],['Calculator in radians for a degree problem','Kalkulator dalam mode radian untuk soal derajat'],['Trusting a sketch as if drawn to scale','Mempercayai sketsa seolah sesuai skala'],['Assuming every triangle is right-angled','Menganggap setiap segitiga siku-siku'],['Forgetting the supplementary sine-rule angle','Melupakan sudut suplementer pada aturan sinus'],['Measuring bearings anticlockwise','Mengukur bearing berlawanan arah jarum jam'],['Measuring elevation/depression from vertical','Mengukur elevasi/depresi dari garis vertikal'],['Rounding an intermediate value too early','Membulatkan nilai perantara terlalu awal'],['Choosing a formula before identifying the triangle','Memilih rumus sebelum menentukan segitiga yang relevan']].map(x=>`<div class="mis-card"><strong>${L(x[0],x[1])}</strong></div>`).join('')}</div></section><section class="scene"><div class="scene-label">${L('FIVE-STEP HABIT','KEBIASAAN LIMA LANGKAH')}</div><div class="formula-flow"><div class="formula">${L('RECOGNIZE → SELECT → CONNECT → SOLVE → VERIFY','KENALI → PILIH → HUBUNGKAN → SELESAIKAN → VERIFIKASI')}</div></div>${mascot('sheet1_bottom_02.png',L('A correct answer is stronger when you can explain why that method belonged to that geometry.','Jawaban benar lebih kuat ketika kamu dapat menjelaskan mengapa metode itu cocok dengan geometri tersebut.'))}</section>${practiceHTML('S')}${completePanel('S')}`}
function renderNav(){const nav=$('#sectionNav');nav.innerHTML=`<button class="section-link ${state.current==='HOME'?'active':''}" data-goto="HOME"><span class="nav-code">⌂</span><span class="nav-copy"><strong>${L('Topic Map','Peta Topik')}</strong><small>${L('Choose a lesson section','Pilih bagian pelajaran')}</small></span><span class="nav-status"></span></button>`+sections.map(s=>`<button class="section-link ${state.current===s.id?'active':''} ${isOpen(s.id)?'':'locked'}" data-goto="${s.id}"><span class="nav-code">${s.id}</span><span class="nav-copy"><strong>${secTitle(s)}</strong><small>${secSub(s)}</small></span><span class="nav-status">${state.completed.includes(s.id)?'✓':isOpen(s.id)?'':'•'}</span></button>`).join('')}
function renderUI(){document.documentElement.lang=state.lang;document.title=`Geometry 5 — ${t('title')}`;$('#brandKicker').textContent='GEOMETRY 5';$('#brandTitle').textContent=t('title');$('#brandBtn').setAttribute('aria-label',L('Open topic map','Buka peta topik'));$('#languageGroup').setAttribute('aria-label',L('Language','Bahasa'));$('#teacherPassLabel').textContent=t('teacherPass');$('#teacherPassBtn').classList.toggle('active',state.teacher);$('#teacherPassBtn').setAttribute('aria-pressed',String(state.teacher));$('#menuBtn').setAttribute('aria-label',L('Open section menu','Buka menu bagian'));$('#sidebar').setAttribute('aria-label',L('Lesson sections','Bagian pelajaran'));$('#progressLabel').textContent=t('progress');$('#previousLabel').textContent=t('previous');$('#nextLabel').textContent=t('next');$('#mapLabel').textContent=t('map');$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===state.lang));const n=state.completed.filter(x=>sections.some(s=>s.id===x)).length;$('#progressText').textContent=`${n} / ${sections.length}`;$('#progressRing').style.background=`conic-gradient(var(--teal) ${n/sections.length*360}deg,#dbe5e4 0)`;renderNav()}
const unitMap={A:unitA,B:unitB,C:unitC,D:unitD,E:unitE,F:unitF,G:unitG,H:unitH,I:unitI,J:unitJ,K:unitK,L:unitL,M:unitM,N:unitN,O:unitO,S:synthesis};
function render(){renderUI();const main=$('#mainContent');if(state.current==='HOME'){main.innerHTML=home()}else if(!isOpen(state.current)){main.innerHTML=`<div class="locked-view"><div class="lock-card"><div class="lock-icon">🔒</div><h2>${t('locked')}</h2><p>${t('lockedHelp')}</p><button class="primary-action" data-goto="HOME">${t('map')}</button></div></div>`}else{main.innerHTML=unitMap[state.current]?unitMap[state.current]():home()}updateFooter();wire();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function updateFooter(){const prev=$('#prevBtn'),next=$('#nextBtn');if(state.current==='HOME'){prev.disabled=true;next.disabled=false;next.dataset.goto='A'}else{const i=sections.findIndex(s=>s.id===state.current);prev.disabled=false;prev.dataset.goto=i===0?'HOME':sections[i-1].id;next.disabled=i===sections.length-1;next.dataset.goto=i===sections.length-1?'HOME':sections[i+1].id} }
function go(id){if(id!=='HOME'&&!isOpen(id)){toast(t('lockedHelp'));return}state.current=id;save();$('#sidebar')?.classList.remove('open');render()}
function complete(id){if(!state.completed.includes(id))state.completed.push(id);save();render();toast(t('completed'))}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),2300)}
function selectQuestion(unit,id,{push=true}={}){const q=QUESTION_BANK[id];if(!q)return;state.practiceLevels[unit]=q.level;state.selectedQuestion[unit]=id;state.hintIndex[id]=0;state.attempts[id]=0;if(push){let h=state.questionHistory[unit]||[];let p=state.historyPos[unit]??h.length-1;if(p<h.length-1)h=h.slice(0,p+1);if(h[h.length-1]!==id)h.push(id);state.questionHistory[unit]=h.slice(-20);state.historyPos[unit]=state.questionHistory[unit].length-1}save();render()}
function nextStructural(unit){const current=ensureQuestion(unit);const level=state.practiceLevels[unit];let pool=bankPool(unit,level);if(pool.length<=1)return current.id;const hist=state.questionHistory[unit]||[];let candidates=pool.filter(q=>q.id!==current.id&&q.family!==current.family&&!hist.slice(-2).includes(q.id));if(!candidates.length)candidates=pool.filter(q=>q.id!==current.id&&!hist.slice(-2).includes(q.id));if(!candidates.length)candidates=pool.filter(q=>q.id!==current.id);const next=candidates[0];selectQuestion(unit,next.id);return next.id}
function wirePractice(){$$('[data-level]').forEach(b=>b.onclick=()=>{const unit=b.dataset.unit,level=b.dataset.level;state.practiceLevels[unit]=level;const pool=bankPool(unit,level);if(pool.length)selectQuestion(unit,pool[0].id);else{save();render()}});$$('[data-practice-unit]').forEach(lab=>{const unit=lab.dataset.practiceUnit;const q=QUESTION_BANK[lab.dataset.qid];if(!q)return;const fb=$('[data-feedback]',lab),hb=$('[data-hint-box]',lab),fs=$('[data-final-support]',lab),sol=$('[data-solution-support]',lab);$('[data-check-practice]',lab).onclick=()=>{const vals=$$('[data-answer]',lab).map(x=>x.value);state.answerDraft[q.id]=vals;const results=q.fields.map((f,i)=>validateField(f,vals[i]));const ok=results.every(Boolean);state.attempts[q.id]=(state.attempts[q.id]||0)+1;fb.className=`feedback show ${ok?'good':'try'}`;if(ok){fb.textContent=L(`Correct — the geometry and calculation agree. ${q.strategyEn} was the key decision.`,`Benar — geometri dan perhitungannya konsisten. ${q.strategyId} adalah keputusan kuncinya.`);const key=unit+':'+q.level;if(!state.solved[key+':'+q.id]){state.solved[key]=(state.solved[key]||0)+1;state.solved[key+':'+q.id]=1}}else{const bad=results.map((v,i)=>v?null:L(q.fields[i].labelEn,q.fields[i].labelId)).filter(Boolean);fb.textContent=L(`${q.wrongEn} Recheck: ${bad.join(', ')}.`,`${q.wrongId} Cek lagi: ${bad.join(', ')}.`)}const hintsUsed=state.hintIndex[q.id]||0;if((state.attempts[q.id]||0)>=2||hintsUsed>=q.hintsEn.length)fs.disabled=false;save()};$('[data-hint-practice]',lab).onclick=()=>{const hints=state.lang==='id'?q.hintsId:q.hintsEn;let i=state.hintIndex[q.id]||0;hb.textContent=hints[Math.min(i,hints.length-1)];hb.classList.add('show');state.hintIndex[q.id]=Math.min(i+1,hints.length);if(state.hintIndex[q.id]>=hints.length)fs.disabled=false;save()};$('[data-final-support]',lab).onclick=()=>{sol.classList.add('show');sol.innerHTML=`<strong>${L('Worked route','Jalur penyelesaian')}:</strong> ${L(q.solutionEn,q.solutionId)}`};$('[data-reset-practice]',lab).onclick=()=>{$$('[data-answer]',lab).forEach(x=>x.value='');state.answerDraft[q.id]=[];fb.className='feedback';hb.className='hint-box';sol.className='solution-support';fs.disabled=true;state.hintIndex[q.id]=0;state.attempts[q.id]=0;save()};$('[data-change-problem]',lab).onclick=()=>nextStructural(unit);$('[data-previous-problem]',lab).onclick=()=>{let h=state.questionHistory[unit]||[],p=state.historyPos[unit]??h.length-1;if(p>0){p--;state.historyPos[unit]=p;const id=h[p];state.selectedQuestion[unit]=id;state.practiceLevels[unit]=QUESTION_BANK[id].level;state.hintIndex[id]=0;save();render()}};const fam=$('[data-family-select]',lab);if(fam)fam.onchange=()=>{const level=state.practiceLevels[unit];let pool=bankPool(unit,level);if(fam.value)pool=pool.filter(x=>x.family===fam.value);if(!pool.length){pool=bankPool(unit).filter(x=>!fam.value||x.family===fam.value)}if(pool[0])selectQuestion(unit,pool[0].id)};const qs=$('[data-question-select]',lab);if(qs)qs.onchange=()=>selectQuestion(unit,qs.value);$$('[data-answer]',lab).forEach((el,i)=>{const store=()=>{const arr=state.answerDraft[q.id]||[];arr[i]=el.value;state.answerDraft[q.id]=arr;save()};el.oninput=store;el.onchange=store});const wp=$('[data-workpad]',lab);if(wp)wp.oninput=()=>{state.workpad[q.id]=wp.value;save()}})}
function wire(){$$('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));$$('[data-complete]').forEach(b=>b.onclick=()=>complete(b.dataset.complete));$$('[data-teacher-complete]').forEach(b=>b.onclick=()=>complete(state.current));$$('[data-reveal-guided]').forEach(btn=>btn.onclick=()=>{const box=btn.closest('[data-guided]');const steps=$$('.reason-step',box);const next=steps.find(x=>!x.classList.contains('show'));if(next){next.classList.add('show')}else{btn.disabled=true;btn.textContent=L('All reasoning shown','Semua langkah sudah ditampilkan')}});$$('[data-bridge-stepper]').forEach(box=>{const panels=itemsFromStepper(box);let index=Math.max(0,Math.min(panels.length-1,Number(box.dataset.bridgeIndex)||0));const sync=()=>{panels.forEach((panel,i)=>panel.hidden=i!==index);box.dataset.bridgeIndex=String(index);const counter=box.querySelector('[data-bridge-counter]');if(counter)counter.textContent=`${index+1}/${panels.length}`;const prev=box.querySelector('[data-bridge-prev]'),next=box.querySelector('[data-bridge-next]');if(prev)prev.disabled=index===0;if(next)next.disabled=index===panels.length-1};box.querySelector('[data-bridge-prev]')?.addEventListener('click',()=>{index=Math.max(0,index-1);state.bridgeSteps??={};state.bridgeSteps[state.current]=index;save();sync()});box.querySelector('[data-bridge-next]')?.addEventListener('click',()=>{index=Math.min(panels.length-1,index+1);state.bridgeSteps??={};state.bridgeSteps[state.current]=index;save();sync()});sync()});wirePractice();
  const methodFeedback=$('#methodFeedback');$$('[data-method-option]').forEach(btn=>{const on=Number(btn.dataset.methodOption)===state.methodChoice;btn.classList.toggle('selected',on);btn.setAttribute('aria-pressed',String(on))});const methodExplainers=[
 ['Pythagoras gives the hypotenuse directly: 5²+12²=13². Trig is unnecessary unless an angle or another side is requested.','Pythagoras langsung memberi hipotenusa: 5²+12²=13². Trigonometri belum perlu kecuali sudut atau sisi lain yang diminta.'],
 ['First find C=180°−42°−73°=65°. The known opposite pair (A,a) then unlocks sine rule for b and c.','Cari dahulu C=180°−42°−73°=65°. Pasangan berhadapan (A,a) lalu memungkinkan aturan sinus untuk b dan c.'],
 ['The known sides enclose the angle: cosine rule finds the third side; the area formula finds area. The target decides which use fits.','Sisi yang diketahui mengapit sudut diketahui: aturan cosinus mencari sisi ketiga; rumus luas mencari luas. Target menentukan pilihan.'],
 ['SSS gives no known opposite pair. Rearrange cosine rule for the angle opposite side 13.','SSS belum memberi pasangan berhadapan dengan sudut diketahui. Susun ulang aturan cosinus untuk sudut di depan sisi 13.'],
 ['A complete opposite pair makes sine rule available. Match each side only with its opposite angle.','Pasangan berhadapan yang lengkap memungkinkan aturan sinus. Pasangkan setiap sisi hanya dengan sudut di depannya.'],
 ['Do not force a rule on incomplete data. Find the missing shared side or angle in a solvable neighbouring triangle.','Jangan memaksakan rumus pada data yang kurang. Cari sisi atau sudut bersama yang hilang pada segitiga tetangga yang dapat diselesaikan.']];
 $$('[data-method-option]').forEach(btn=>btn.onclick=()=>{const i=Number(btn.dataset.methodOption);state.methodChoice=i;save();$$('[data-method-option]').forEach(x=>{x.classList.toggle('selected',x===btn);x.setAttribute('aria-pressed',String(x===btn))});if(methodFeedback){methodFeedback.className='quiz-feedback show';methodFeedback.textContent=L(methodExplainers[i][0],methodExplainers[i][1])}});

  const pairNotes={a:L('Side a=BC lies opposite angle A. Both are highlighted together.','Sisi a=BC berada di depan sudut A. Keduanya disorot bersama.'),b:L('Side b=CA lies opposite angle B. Both are highlighted together.','Sisi b=CA berada di depan sudut B. Keduanya disorot bersama.'),c:L('Side c=AB lies opposite angle C. Both are highlighted together.','Sisi c=AB berada di depan sudut C. Keduanya disorot bersama.')};
 const applyPair=key=>{const root=$('#pairMapper');if(!root)return;root.querySelectorAll('[data-pair-side],[data-pair-angle],[data-pair-text]').forEach(el=>{const on=el.dataset.pairSide===key||el.dataset.pairAngle===key||el.dataset.pairText===key;el.classList.toggle('pair-selected',on);el.classList.toggle('pair-muted',!on)});$$('[data-pair]').forEach(x=>{x.classList.toggle('active',x.dataset.pair===key);x.setAttribute('aria-pressed',String(x.dataset.pair===key))});$('#pairNote').textContent=pairNotes[key]};
 if($('#pairMapper'))applyPair(state.pairFocus||'a');$$('[data-pair]').forEach(btn=>btn.onclick=()=>{state.pairFocus=btn.dataset.pair;save();applyPair(state.pairFocus)});

  const amb=$('[data-ambig-reveal]');if(amb){const syncAmb=()=>{const on=!!state.ambigRevealed;$('.ambiguous-svg').classList.toggle('revealed',on);amb.classList.toggle('active',on);amb.setAttribute('aria-pressed',String(on));$('#ambigNote').textContent=on?L('The circle of radius a meets the admissible ray at B₁ and B₂. Both radii have equal length; both triangles share b and angle A.','Lingkaran berjari-jari a memotong sinar di B₁ dan B₂. Kedua jari-jari sama panjang; kedua segitiga berbagi b dan sudut A.'):L('One configuration is shown. Reveal the construction to see whether the same fixed length reaches the ray again.','Satu konfigurasi ditampilkan. Tunjukkan konstruksi untuk melihat apakah panjang tetap yang sama mencapai sinar sekali lagi.')};syncAmb();amb.onclick=()=>{state.ambigRevealed=!state.ambigRevealed;save();syncAmb()}}

  const cr=$('[data-cos-range]');if(cr){const root=$('#cosExplorer');const syncCos=()=>{const angle=Number(cr.value),c=Math.sqrt(7*7+10*10-2*7*10*Math.cos(angle*Math.PI/180));state.cosAngle=angle;save();updateCosExplorer(root,angle);$('[data-cos-angle]').textContent=angle+'°';cr.setAttribute('aria-valuenow',String(angle));$('[data-cos-note]').textContent=cosineCaseNote(angle,c)};syncCos();cr.addEventListener('input',syncCos);cr.addEventListener('change',syncCos)};$$('[data-cos-use]').forEach(btn=>btn.addEventListener('click',()=>{state.cosUse=btn.dataset.cosUse;save();$$('[data-cos-use]').forEach(x=>{const on=x.dataset.cosUse===state.cosUse;x.setAttribute('aria-pressed',String(on))});$$('[data-cos-use-panel]').forEach(panel=>panel.hidden=panel.dataset.cosUsePanel!==state.cosUse)}));

  const br=$('[data-bearing-range]');if(br){const svg=$('#bearingExplorer svg');const syncBearing=()=>{const beta=Number(br.value),E=18*Math.sin(beta*Math.PI/180),N=18*Math.cos(beta*Math.PI/180);state.bearing=beta;save();updateCompass(svg,beta);br.setAttribute('aria-valuenow',String(beta));$('[data-bearing-value]').textContent=String(beta).padStart(3,'0')+'°';$('[data-east]').textContent=fmt(E,1);$('[data-north]').textContent=fmt(N,1)};syncBearing();br.addEventListener('input',syncBearing);br.addEventListener('change',syncBearing)};

  const gatewayRoot=$('#gatewayDiagram');if(gatewayRoot){$$('[data-gateway-step]').forEach(btn=>btn.onclick=()=>{const step=Number(btn.dataset.gatewayStep);state.gatewayStep=step;save();$$('[data-gateway-step]').forEach(x=>{const active=Number(x.dataset.gatewayStep)===step;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});gatewayRoot.innerHTML=gatewaySvg(step);$('#gatewayNote').textContent=gatewayStepText(step)})}
  const fr=$('[data-feasible-range]');if(fr){const root=$('#feasibleExplorer'),status=$('[data-feasible-status]'),note=$('[data-feasible-note]'),value=$('[data-feasible-value]');const sync=b=>{const g=updateFeasibility(root,b);value.textContent=fmt(b,3);status.textContent=g.count===0?L('0 configurations','0 konfigurasi'):g.count===1?L('1 configuration','1 konfigurasi'):L('2 configurations','2 konfigurasi');$$('[data-feasible-count]',root).forEach(x=>x.classList.toggle('active',Number(x.dataset.feasibleCount)===g.count));note.textContent=feasibleNote(g,b)};const updateFromSlider=()=>{const b=Number(fr.value);state.feasibleB=b;save();sync(b)};sync(Number(fr.value));fr.addEventListener('input',updateFromSlider);fr.addEventListener('change',updateFromSlider);const tangent=$('[data-tangent-boundary]');tangent.onclick=()=>{const b=feasibleGeom(Number(fr.value)).critical;state.feasibleB=b;fr.value=String(b);save();sync(b)}}
  $$('[data-route]').forEach(b=>b.onclick=()=>{const route=b.dataset.route;state.route=route;save();$$('[data-route]').forEach(x=>{const active=x.dataset.route===route;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});$$('[data-route-panel]').forEach(x=>x.classList.toggle('show',x.dataset.routePanel===route));const diagram=$('#chordDiagram');if(diagram)diagram.innerHTML=chordSvg(route)})
}
